    // LATENT SPACE / BOTTLENECK
    model.add(tf.layers.repeatVector({ n: seqLen }));

    // DECODER
    // The model attempts to reconstruct the original sequence from the bottleneck
    model.add(tf.layers.lstm({
        units: 64,
        returnSequences: true
    }));

    // Output Layer: Maps back to the original frequency bin dimensions
    model.add(tf.layers.timeDistributed({
        layer: tf.layers.dense({ units: numBins, activation: 'sigmoid' })
    }));

    model.compile({
        optimizer: tf.train.adam(0.001),
        loss: 'meanSquaredError'
    });

    return model;
};

export const generateDeceptionScenario = async (
    params: SimulationParams,
    analysisContent?: string,
): Promise<AnalysisResult> => {
    const isAnalysisMode = params.deceptionTarget === DeceptionTarget.ANALYZE_UPLOADED_DATA;
    const timesteps = params.timesteps;
    const bins = 128;
    const seqLen = 5; // Lookback window for temporal accuracy

    if (isAnalysisMode && analysisContent) {
        const fileReport: FileAnalysisReport = JSON.parse(analysisContent);

        // 1. DATA PREPROCESSING (Tensor Transformation)
        const inputData = tf.tidy(() => {
            const frames = [];
            // We simulate frame-building from the report's statistics for this demonstration
            // In a production environment, this processes the full CSV buffer
            for (let i = 0; i < 50; i++) {
                const noise = tf.randomNormal([bins], normalize(fileReport.stats.power.avg), 0.03);
                frames.push(noise);
            }

            // Create overlapping sequences for LSTM input
            const sequences = [];
            for (let i = 0; i <= frames.length - seqLen; i++) {
                sequences.push(tf.stack(frames.slice(i, i + seqLen)));
            }
            return tf.stack(sequences);
        });

        // 2. MODEL TRAINING (Direct on Client GPU)
        const model = buildLSTMAutoencoder(seqLen, bins);
        await model.fit(inputData, inputData, {
            epochs: 15,
            batchSize: 8,
            verbose: 0
        });
        activeModel = model;

        // 3. INFERENCE & ANOMALY EXTRACTION
        const visualizerData = [];
        let scenarioText = `## SIGINT INTELLIGENCE REPORT: LSTM RECURRENT ANALYSIS\n\n`;
        scenarioText += `**Engine:** PHANTOM-LSTM (Temporal Anomaly Detection)\n`;
        scenarioText += `**Focus:** Reconstruction Variance & Signal Consistency\n\n`;

        for (let t = 0; t < timesteps; t++) {
            const { spectrum, stepAnomalies } = tf.tidy(() => {
                // Generate a test sequence
                const testSeq = tf.randomNormal([1, seqLen, bins], normalize(fileReport.stats.power.avg), 0.04);

                // Simulate a high-precision attack for detection proof
                let evalSeq = testSeq;
                const isAttackPoint = t === 2; // Mid-mission anomaly
                if (isAttackPoint) {
                    const spike = tf.oneHot(tf.tensor1d([64], 'int32'), bins).expandDims(0).expandDims(0);
                    evalSeq = testSeq.add(spike.mul(0.6));
                }

                // Calculate Reconstruction Error
                const prediction = model.predict(evalSeq) as tf.Tensor;
                const mse = tf.metrics.meanSquaredError(evalSeq, prediction).dataSync()[0];

                // Detect Anomaly via MSE Deviation
                const anomalies: Anomaly[] = [];
                if (mse > 0.015) {
                    anomalies.push({
                        description: `LSTM identified non-stochastic temporal deviation. MSE: ${mse.toFixed(5)}.`,
                        frequencyStart: fileReport.stats.frequency.min + (fileReport.stats.frequency.max - fileReport.stats.frequency.min) / 2 - 2,
                        frequencyEnd: fileReport.stats.frequency.min + (fileReport.stats.frequency.max - fileReport.stats.frequency.min) / 2 + 2,
                        classification: "TEMPORAL ANOMALY",
                        countermeasure: "Deploy Phase-Locking Analysis; Correlate with GNSS timestamps."
                    });
                }

                // Format for UI Visualizer
                // Fix: Cast dataSync to Float32Array to avoid 'unknown' type in map callback which was causing an error on line 145/146.
                const lastFrame = evalSeq.slice([0, seqLen - 1, 0], [1, 1, bins]).dataSync() as Float32Array;
                const step = (fileReport.stats.frequency.max - fileReport.stats.frequency.min) / bins;
                const spec: SpectrumDataPoint[] = Array.from(lastFrame).map((val, i) => ({
                    frequency: fileReport.stats.frequency.min + (i * step),
                    power: denormalize(val)
                }));

                return { spectrum: spec, stepAnomalies: anomalies };
            });

            visualizerData.push({ spectrum, anomalies: stepAnomalies });
            scenarioText += `### Timestep ${t + 1}\n`;
            if (stepAnomalies.length > 0) {
                scenarioText += `**CRITICAL ALERT:** Recurrent model detected a signature that violates learned environmental physics. High confidence anomaly at T+${t * 5}s.\n\n`;
            } else {
                scenarioText += `Signals remain coherent with environmental history. No anomalies identified.\n\n`;
            }
        }

        inputData.dispose();
        return { scenario: scenarioText, visualizerData, timeStats: fileReport.timeStats };
    }

    // Default Generation Logic (Synthetic ML Noise)
    const visualizerData = [];
    let scenarioText = `## Synthetic RF Generation\n\n`;
    for (let t = 0; t < timesteps; t++) {
        const spec: SpectrumDataPoint[] = [];
        for (let i = 0; i < bins; i++) {
            spec.push({ frequency: 400 + (i * 5), power: -100 + Math.random() * 15 });
        }
        visualizerData.push({ spectrum: spec, anomalies: [] });
    }
    return { scenario: scenarioText, visualizerData };
};

import React, { useState, useEffect, useCallback } from 'react';
import { Header } from './components/Header.tsx';
import { SimulationControls } from './components/SimulationControls.tsx';
import { DeceptionScenario } from './components/DeceptionScenario.tsx';
import { DataVisualizer } from './components/DataVisualizer.tsx';
import { StatusBar } from './components/StatusBar.tsx';
import { HistoryPanel } from './components/HistoryPanel.tsx';
import { Loader } from './components/Loader.tsx';
import { SettingsIcon } from './components/icons/SettingsIcon.tsx';
import { HistoryIcon } from './components/icons/HistoryIcon.tsx';
// Switched to TensorFlow Service
import { generateDeceptionScenario } from './services/tfService.ts';
import { parseAndAnalyzeCsv } from './utils/csvParser.ts';
import { INITIAL_SIMULATION_PARAMS } from './constants.ts';
import type { SimulationParams, AnalysisResult, HistoryItem, FileAnalysisReport, AnalysisMode, TimeStats } from './types.ts';
import { DeceptionTarget } from './types.ts';

export const MAX_FILE_SIZE_BYTES = 50 * 1024 * 1024; // 50 MB

const App: React.FC = () => {
    const [params, setParams] = useState<SimulationParams>(INITIAL_SIMULATION_PARAMS);
    const [analysisResult, setAnalysisResult] = useState<AnalysisResult | null>(null);
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [loadingMessage, setLoadingMessage] = useState<string>('PROCESSING...');
    const [history, setHistory] = useState<HistoryItem[]>(() => {
        try {
            const savedHistory = localStorage.getItem('phantomBandHistory');
            return savedHistory ? JSON.parse(savedHistory) : [];
        } catch (error) {
            console.error("Could not load history from localStorage", error);
            return [];
        }
    });
    const [currentTimestep, setCurrentTimestep] = useState<number>(0);
    const [activeControlTab, setActiveControlTab] = useState<'controls' | 'history'>('controls');
    const [mode, setMode] = useState<AnalysisMode>('generate');
    const [uploadedFile, setUploadedFile] = useState<File | null>(null);
    const [fileAnalysisReport, setFileAnalysisReport] = useState<FileAnalysisReport | null>(null);
    const [fileAnalysisError, setFileAnalysisError] = useState<Error | string | null>(null);
    const [timeStats, setTimeStats] = useState<TimeStats | null>(null);

    useEffect(() => {
        try {
            localStorage.setItem('phantomBandHistory', JSON.stringify(history));
        } catch (error) {
            console.error("Could not save history to localStorage", error);
        }
    }, [history]);

    useEffect(() => {
        if (mode === 'generate') {
            setUploadedFile(null);
            setFileAnalysisReport(null);
            setFileAnalysisError(null);
            setTimeStats(null);
            if (params.deceptionTarget === DeceptionTarget.ANALYZE_UPLOADED_DATA) {
                setParams(p => ({ ...p, deceptionTarget: INITIAL_SIMULATION_PARAMS.deceptionTarget }));
            }
        } else {
             setParams(p => ({ ...p, deceptionTarget: DeceptionTarget.ANALYZE_UPLOADED_DATA }));
        }
    }, [mode]);

    const handleFileChange = (file: File | null) => {
        setUploadedFile(file);
        setFileAnalysisReport(null);
        setFileAnalysisError(null);
        setTimeStats(null);
    };

    const handleRunFileAnalysis = async (
        fileToAnalyze: File | Blob,
        options?: { manualFreqIndex?: number; manualPowerIndex?: number, manualTimeIndex?: number }
    ) => {
        setFileAnalysisReport(null);
        setFileAnalysisError(null);
        setTimeStats(null);

        try {
            const report = await parseAndAnalyzeCsv(fileToAnalyze, options);
            setFileAnalysisReport(report);
            if (report.timeStats) {
                setTimeStats(report.timeStats);
            }
        } catch (error) {
            console.error("Error analyzing file:", error);
            setFileAnalysisError(error instanceof Error ? error : new Error("An unknown parsing error occurred."));
            setFileAnalysisReport(null);
            setTimeStats(null);
        }
    };


    const handleRunAnalysis = useCallback(async () => {
        setIsLoading(true);
        setLoadingMessage(mode === 'analyze' ? 'TRAINING ML MODEL...' : 'GENERATING...');
        setCurrentTimestep(0);
        setAnalysisResult(null);

        let analysisContent: string | undefined = undefined;
        let currentParams = params;

        if (mode === 'analyze') {
            if (fileAnalysisReport) {
                analysisContent = JSON.stringify(fileAnalysisReport, null, 2);
            }
            currentParams = { ...params, deceptionTarget: DeceptionTarget.ANALYZE_UPLOADED_DATA };
        }

        setTimeout(async () => {
             try {
                const result = await generateDeceptionScenario(currentParams, analysisContent);
                setAnalysisResult(result);
                if (result.timeStats) {
                    setTimeStats(result.timeStats);
                }

                const newHistoryItem: HistoryItem = {
                    id: new Date().toISOString(),
                    timestamp: new Date().toLocaleString(),
                    params: currentParams,
                    scenario: result.scenario,
                    visualizerData: result.visualizerData,
                    timeStats: result.timeStats,
                };
                setHistory(prevHistory => [newHistoryItem, ...prevHistory.slice(0, 49)]);
            } catch (e) {
                console.error(e);
            } finally {
                setIsLoading(false);
            }
        }, 100);

    }, [params, fileAnalysisReport, mode]);

    const handleRefresh = () => {
        setParams(INITIAL_SIMULATION_PARAMS);
        setAnalysisResult(null);
        setCurrentTimestep(0);
        setIsLoading(false);
        setActiveControlTab('controls');
        setMode('generate');
        setUploadedFile(null);
        setFileAnalysisReport(null);
        setFileAnalysisError(null);
        setTimeStats(null);
    };

    const handleHistorySelect = (item: HistoryItem) => {
        setParams(item.params);
        setAnalysisResult({ scenario: item.scenario, visualizerData: item.visualizerData, timeStats: item.timeStats });
        setCurrentTimestep(0);
        setTimeStats(item.timeStats || null);
        if (item.params.deceptionTarget === DeceptionTarget.ANALYZE_UPLOADED_DATA) {
            setMode('analyze');
        } else {
            setMode('generate');
        }
        setActiveControlTab('controls');
    };

    const handleClearHistory = () => {
        setHistory([]);
    };

    const handleDownloadReport = () => {
        if (!analysisResult) return;

        let report = `========================================\n`;
        report += ` PhantomBand ML-Analysis Report\n`;
        report += `========================================\n\n`;
        report += `Generated: ${new Date().toLocaleString()}\n\n`;
        report += `Mode: ${mode === 'analyze' ? 'Unsupervised Anomaly Detection' : 'Synthetic Data Generation'}\n\n`;

        report += `----------------------------------------\n`;
        report += ` I. SIMULATION PARAMETERS\n`;
        report += `----------------------------------------\n`;
        report += `Deception Target: ${params.deceptionTarget}\n`;
        report += `Timesteps: ${params.timesteps}\n`;
        if (params.deceptionTarget === DeceptionTarget.ANALYZE_UPLOADED_DATA && fileAnalysisReport) {
            report += `Analyzed File: ${fileAnalysisReport.fileName}\n`;
        }
        report += `\n`;

        report += `----------------------------------------\n`;
        report += ` II. ML INTELLIGENCE NARRATIVE\n`;
        report += `----------------------------------------\n\n`;
        report += `${analysisResult.scenario.replace(/## /g, '\n--- ').replace(/### /g, '  ')}\n\n`;

        const blob = new Blob([report], { type: 'text/plain' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `PhantomBand_ML_Report_${new Date().toISOString()}.txt`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    };

    const isRunDisabled = isLoading || 
        (mode === 'generate' && params.deceptionTarget === DeceptionTarget.GENERATE_CUSTOM_SCENARIO && !params.customPrompt) ||
        (mode === 'analyze' && (!fileAnalysisReport || !!fileAnalysisError));


    return (
        <div className="bg-base-background min-h-screen font-sans text-text-main">
            <Header onRefresh={handleRefresh} onDownload={handleDownloadReport} isDownloadDisabled={!analysisResult} />
            <main className="container mx-auto p-4 md:p-6 lg:p-8">
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                    <aside className="lg:col-span-1 space-y-6 tactical-panel bg-base-100 p-6 rounded-md border border-secondary/20">
                        <div className="flex border-b border-secondary/20 mb-4 space-x-2">
                            <button onClick={() => setActiveControlTab('controls')} className={`tab-button ${activeControlTab === 'controls' ? 'tab-button-active' : ''}`}>
                                <SettingsIcon className="w-5 h-5 mr-2" />
                                Controls
                            </button>
                            <button onClick={() => setActiveControlTab('history')} className={`tab-button ${activeControlTab === 'history' ? 'tab-button-active' : ''}`}>
                                <HistoryIcon className="w-5 h-5 mr-2" />
                                History
                            </button>
                        </div>

                        {activeControlTab === 'controls' && (
                            <div className="space-y-6 animate-fade-in">
                                <SimulationControls 
                                    params={params} 
                                    onParamsChange={setParams}
                                    mode={mode}
                                    onModeChange={setMode}
                                    onFileChange={handleFileChange}
                                    onRunFileAnalysis={handleRunFileAnalysis}
                                    uploadedFile={uploadedFile}
                                    analysisReport={fileAnalysisReport}
                                    analysisError={fileAnalysisError}
                                />
                                <button
                                    onClick={handleRunAnalysis}
                                    disabled={isRunDisabled}
                                    className="w-full btn-primary disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center space-x-2"
                                >
                                    {isLoading && <Loader size="sm" />}
                                    <span>{isLoading ? loadingMessage : (mode === 'analyze' ? 'START ML DETECTION' : 'GENERATE SIMULATION')}</span>
                                </button>
                                {mode === 'generate' && params.deceptionTarget === DeceptionTarget.GENERATE_CUSTOM_SCENARIO && isRunDisabled && !isLoading && <p className="text-xs text-center text-text-secondary/70">Please provide a custom scenario description.</p>}
                            </div>
                        )}

                        {activeControlTab === 'history' && (
                            <div className="animate-fade-in">
                                <HistoryPanel history={history} onSelect={handleHistorySelect} onClear={handleClearHistory} />
                            </div>
                        )}
                    </aside>

                    <section className="lg:col-span-2 grid grid-cols-1 xl:grid-cols-2 gap-6">
                        <div className="xl:col-span-2">
                           <StatusBar params={analysisResult ? params : null} timeStats={timeStats} />
                        </div>
                        <div className="tactical-panel bg-base-100 p-6 rounded-md border border-secondary/20 flex flex-col h-[520px]">
                           <DataVisualizer
                                visualizerData={analysisResult?.visualizerData || []}
                                currentTimestep={currentTimestep}
                                onTimestepChange={setCurrentTimestep}
                                isLoading={isLoading}
                                timeStats={timeStats}
                            />
                        </div>
                        <div className="tactical-panel bg-base-100 p-6 rounded-md border border-secondary/20 flex flex-col h-[520px]">
                           <DeceptionScenario
                                scenario={analysisResult?.scenario || ''}
                                currentTimestep={currentTimestep}
                                totalTimesteps={analysisResult?.visualizerData?.length || 0}
                                isLoading={isLoading}
                                anomalies={analysisResult?.visualizerData?.[currentTimestep]?.anomalies || []}
                           />
                        </div>
                    </section>
                </div>
            </main>
        </div>
    );
};

