import { MAX_FILE_SIZE_BYTES } from '../constants.ts';
import { ColumnDetectionError } from '../utils/csvParser';


type Segment = 'start' | 'middle' | 'end';

interface ParseOptions {
    manualFreqIndex?: number;
    manualPowerIndex?: number;
    manualTimeIndex?: number;
}

interface FileUploadProps {
  onFileChange: (file: File | null) => void;
  onRunFileAnalysis: (file: File | Blob, options?: ParseOptions) => void;
  uploadedFile: File | null;
  analysisReport: FileAnalysisReport | null;
  analysisError: Error | string | null;
}

const ReportStat: React.FC<{ label: string, value: string | number }> = ({ label, value }) => (
    <div className="flex justify-between items-baseline">
        <p className="text-text-secondary">{label}:</p>
        <p className="font-semibold text-text-main">{value}</p>
    </div>
);

export const FileUpload: React.FC<FileUploadProps> = ({ onFileChange, onRunFileAnalysis, uploadedFile, analysisReport, analysisError }) => {
  const [isDragOver, setIsDragOver] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isLargeFile, setIsLargeFile] = useState(false);
  const [manualFreqIndex, setManualFreqIndex] = useState<number | string>('');
  const [manualPowerIndex, setManualPowerIndex] = useState<number | string>('');
  const [manualTimeIndex, setManualTimeIndex] = useState<number | string>('');


  useEffect(() => {
    // When a new file is uploaded or the error is cleared, reset manual selection
    if (!analysisError || !uploadedFile) {
        setManualFreqIndex('');
        setManualPowerIndex('');
        setManualTimeIndex('');
    }
  }, [analysisError, uploadedFile]);

  useEffect(() => {
    if (uploadedFile) {
      setIsLargeFile(uploadedFile.size > MAX_FILE_SIZE_BYTES);
      if (uploadedFile.size <= MAX_FILE_SIZE_BYTES) {
        onRunFileAnalysis(uploadedFile);
      }
    } else {
      setIsLargeFile(false);
    }
  }, [uploadedFile]);

  const handleFileChangeInternal = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files ? event.target.files[0] : null;
    onFileChange(file);
  };

  const handleAnalyzeSegment = (segment: Segment) => {
    if (!uploadedFile) return;

    let start = 0;
    let end = MAX_FILE_SIZE_BYTES;

    if (segment === 'middle') {
        start = Math.max(0, Math.floor(uploadedFile.size / 2) - (MAX_FILE_SIZE_BYTES / 2));
        end = start + MAX_FILE_SIZE_BYTES;
    } else if (segment === 'end') {
        start = Math.max(0, uploadedFile.size - MAX_FILE_SIZE_BYTES);
        end = uploadedFile.size;
    }

    const fileSlice = uploadedFile.slice(start, end);
    const slicedFile = new File([fileSlice], `${uploadedFile.name} [${segment}]`, { type: uploadedFile.type });
    onRunFileAnalysis(slicedFile);
  };

  const handleConfirmSelection = () => {
    if (uploadedFile && manualFreqIndex !== '' && manualPowerIndex !== '') {
        onRunFileAnalysis(uploadedFile, {
            manualFreqIndex: Number(manualFreqIndex),
            manualPowerIndex: Number(manualPowerIndex),
            manualTimeIndex: manualTimeIndex !== '' ? Number(manualTimeIndex) : undefined
        });
    }
  };

  const handleDragOver = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setIsDragOver(true);
  };

  const handleDragLeave = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setIsDragOver(false);
  };

  const handleDrop = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setIsDragOver(false);
    const file = event.dataTransfer.files ? event.dataTransfer.files[0] : null;
    if (file) {
      onFileChange(file);
      if (fileInputRef.current) {
        fileInputRef.current.files = event.dataTransfer.files;
      }
    }
  };

  const handleClick = () => {
    if (!uploadedFile && !analysisError) {
        fileInputRef.current?.click();
    }
  };

  const handleClearFile = (e: React.MouseEvent) => {
    e.stopPropagation(); // Prevent click from triggering file input
    onFileChange(null);
    if(fileInputRef.current) {
        fileInputRef.current.value = "";
    }
  }

  const baseClasses = "border border-dashed rounded-md p-4 text-center transition-all duration-300";
  const idleClasses = "cursor-pointer bg-base-100/50 border-secondary";
  const dragClasses = isDragOver ? 'border-primary-amber scale-105' : 'border-secondary';

  const renderContent = () => {
      if (analysisError instanceof ColumnDetectionError) {
            const headers = analysisError.headers;
            const selectedIndices = [manualFreqIndex, manualPowerIndex, manualTimeIndex].filter(i => i !== '').map(Number);
            const hasDuplicates = new Set(selectedIndices).size !== selectedIndices.length;

            return (
                <div className={`${baseClasses} border-amber-500/80 text-left animate-fade-in`}>
                     <div className="flex justify-between items-center mb-3">
                        <p className="font-semibold text-amber-400 text-sm uppercase">Manual Column Selection</p>
                        <button onClick={handleClearFile} className="text-xs text-text-secondary hover:text-red-400">&times; Clear</button>
                    </div>
                    <p className="text-xs text-text-secondary mb-3">
                        We couldn't automatically detect all columns. Please select them below.
                    </p>
                    <div className="space-y-4">
                        <div>
                             <label className="block text-sm font-medium text-text-secondary mb-1">Frequency Column</label>
                             <select
                                 value={manualFreqIndex}
                                 onChange={(e) => setManualFreqIndex(e.target.value)}
                                 className="w-full bg-base-300 border border-secondary/50 rounded-md py-2 px-3 focus:outline-none focus:ring-2 focus:ring-primary-amber text-text-main"
                             >
                                 <option value="" disabled>Select a column...</option>
                                 {headers.map((h, i) => <option key={i} value={i}>{h}</option>)}
                             </select>
                        </div>
                         <div>
                             <label className="block text-sm font-medium text-text-secondary mb-1">Power Column</label>
                             <select
                                 value={manualPowerIndex}
                                 onChange={(e) => setManualPowerIndex(e.target.value)}
                                 className="w-full bg-base-300 border border-secondary/50 rounded-md py-2 px-3 focus:outline-none focus:ring-2 focus:ring-primary-amber text-text-main"
                             >
                                  <option value="" disabled>Select a column...</option>
                                 {headers.map((h, i) => <option key={i} value={i}>{h}</option>)}
                             </select>
                        </div>
                        <div>
                             <label className="block text-sm font-medium text-text-secondary mb-1">Timestamp Column (Optional)</label>
                             <select
                                 value={manualTimeIndex}
                                 onChange={(e) => setManualTimeIndex(e.target.value)}
                                 className="w-full bg-base-300 border border-secondary/50 rounded-md py-2 px-3 focus:outline-none focus:ring-2 focus:ring-primary-amber text-text-main"
                             >
                                  <option value="">None</option>
                                 {headers.map((h, i) => <option key={i} value={i}>{h}</option>)}
                             </select>
                        </div>
                    </div>
                    <button
                        onClick={handleConfirmSelection}
                        disabled={manualFreqIndex === '' || manualPowerIndex === '' || hasDuplicates}
                        className="btn-primary w-full mt-4 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        Confirm & Analyze
                    </button>
                    {hasDuplicates && (
                        <p className="text-xs text-center text-red-400 mt-2">Each column selection must be unique.</p>
                    )}
                </div>
            );
      }

      if (analysisError) {
        return (
            <div className={`${baseClasses} border-red-500/80 text-left animate-fade-in`}>
                <div className="flex justify-between items-center mb-3">
                    <p className="font-semibold text-red-400 text-sm uppercase">File Analysis Error</p>
                    <button onClick={handleClearFile} className="text-xs text-text-secondary hover:text-red-400">&times; Clear</button>
                </div>
                <div className="space-y-2 text-xs font-mono bg-red-900/30 p-3 rounded-md text-red-300">
                    <p>{typeof analysisError === 'string' ? analysisError : analysisError.message}</p>
                </div>
                <p className="text-xs text-text-secondary/70 mt-3 text-center">
                    Please upload a different file or check the file format.
                </p>
            </div>
        );
      }

      if (analysisReport) {
        return (
            <div className={`${baseClasses} border-primary-amber text-left animate-fade-in`}>
                <div className="flex justify-between items-center mb-3">
                    <p className="font-semibold text-primary-amber text-sm uppercase">Pre-Analysis Report</p>
                    <button onClick={handleClearFile} className="text-xs text-text-secondary hover:text-red-400">&times; Clear</button>
                </div>
                <div className="space-y-2 text-xs font-mono bg-base-300/50 p-3 rounded-md">
                    <ReportStat label="File" value={analysisReport.fileName} />
                    {analysisReport.timeStats && <ReportStat label="Duration" value={`${analysisReport.timeStats.durationSeconds.toFixed(1)}s`} />}
                    <ReportStat label="Rows" value={analysisReport.rowCount.toLocaleString()} />
                    <ReportStat label="Columns" value={analysisReport.columnCount} />
                    <hr className="border-secondary/20 my-2" />
                    <ReportStat label="Freq Range (MHz)" value={`${analysisReport.stats.frequency.min.toFixed(2)} - ${analysisReport.stats.frequency.max.toFixed(2)}`} />
                    <ReportStat label="Power Range (dBm)" value={`${analysisReport.stats.power.min.toFixed(2)} - ${analysisReport.stats.power.max.toFixed(2)}`} />
                    <ReportStat label="Avg Power (dBm)" value={analysisReport.stats.power.avg.toFixed(2)} />
                </div>
                <p className="text-xs text-text-secondary/70 mt-3 text-center">
                    A summary of this data will be sent to the AI for analysis.
                </p>
            </div>
        );
      }

      if (uploadedFile && isLargeFile) {
        const fileSizeMB = (uploadedFile.size / 1024 / 1024).toFixed(1);
        return (
            <div className={`${baseClasses} border-amber-500/80 text-left animate-fade-in`}>
                <div className="flex justify-between items-center mb-3">
                    <p className="font-semibold text-amber-400 text-sm uppercase">Large File Detected</p>
                    <button onClick={handleClearFile} className="text-xs text-text-secondary hover:text-red-400">&times; Clear</button>
                </div>
                <p className="text-xs text-center text-text-secondary mb-3">File size is {fileSizeMB} MB. Please select a 50 MB segment to analyze.</p>
                <div className="flex flex-col space-y-2">
                    <button onClick={() => handleAnalyzeSegment('start')} className="btn-secondary text-sm w-full">Analyze First 50 MB (Ingress)</button>
                    <button onClick={() => handleAnalyzeSegment('middle')} className="btn-secondary text-sm w-full">Analyze Middle 50 MB (Mid-Mission)</button>
                    <button onClick={() => handleAnalyzeSegment('end')} className="btn-secondary text-sm w-full">Analyze Last 50 MB (Egress)</button>
                </div>
            </div>
        );
      }

      return (
        <div
            className={`${baseClasses} ${idleClasses} ${dragClasses}`}
            onClick={handleClick}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
            style={{ minHeight: '180px' }}
        >
            <div className="flex flex-col items-center justify-center space-y-2 text-text-secondary h-full">
                <FileCodeIcon className="w-8 h-8 mb-1" />
                <div>
                <p>
                    <span className="font-semibold text-primary-amber">UPLOAD FILE</span> or drag & drop
                </p>
                <p className="text-xs text-text-secondary/70">.csv & .txt files only</p>
                </div>
            </div>
        </div>
      );
  };

  return (
    <div>
      <input
        type="file"
        ref={fileInputRef}
        onChange={handleFileChangeInternal}
        className="hidden"
        accept=".csv,.txt"
      />
      {renderContent()}
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Header } from './components/Header.tsx';
import { SimulationControls } from './components/SimulationControls.tsx';
import { DeceptionScenario } from './components/DeceptionScenario.tsx';
import { DataVisualizer } from './components/DataVisualizer.tsx';
import { StatusBar } from './components/StatusBar.tsx';
import { HistoryPanel } from './components/HistoryPanel.tsx';
import { Loader } from './components/Loader.tsx';
import { SettingsIcon } from './components/icons/SettingsIcon.tsx';
import { HistoryIcon } from './components/icons/HistoryIcon.tsx';
import { generateDeceptionScenario } from './services/tfService.ts';
import { parseAndAnalyzeCsv } from './utils/csvParser.ts';
import { INITIAL_SIMULATION_PARAMS } from './constants.ts';
import type { SimulationParams, AnalysisResult, HistoryItem, FileAnalysisReport, TimeStats } from './types.ts';

const App: React.FC = () => {
    const [params, setParams] = useState<SimulationParams>(INITIAL_SIMULATION_PARAMS);
    const [analysisResult, setAnalysisResult] = useState<AnalysisResult | null>(null);
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [loadingMessage, setLoadingMessage] = useState<string>('PHANTOM-LSTM TRAINING...');
    const [history, setHistory] = useState<HistoryItem[]>(() => {
        try {
            const savedHistory = localStorage.getItem('phantomBandHistory');
            return savedHistory ? JSON.parse(savedHistory) : [];
        } catch (error) {
            return [];
        }
    });
    const [currentTimestep, setCurrentTimestep] = useState<number>(0);
    const [activeControlTab, setActiveControlTab] = useState<'controls' | 'history'>('controls');
    const [uploadedFile, setUploadedFile] = useState<File | null>(null);
    const [fileAnalysisReport, setFileAnalysisReport] = useState<FileAnalysisReport | null>(null);
    const [fileAnalysisError, setFileAnalysisError] = useState<Error | string | null>(null);
    const [timeStats, setTimeStats] = useState<TimeStats | null>(null);

    useEffect(() => {
        try {
            localStorage.setItem('phantomBandHistory', JSON.stringify(history));
        } catch (error) {}
    }, [history]);

    const handleFileChange = (file: File | null) => {
        setUploadedFile(file);
        setFileAnalysisReport(null);
        setFileAnalysisError(null);
        setTimeStats(null);
    };

    const handleRunFileAnalysis = async (
        fileToAnalyze: File | Blob,
        options?: { manualFreqIndex?: number; manualPowerIndex?: number, manualTimeIndex?: number }
    ) => {
        try {
            const report = await parseAndAnalyzeCsv(fileToAnalyze, options);
            setFileAnalysisReport(report);
            if (report.timeStats) setTimeStats(report.timeStats);
        } catch (error) {
            setFileAnalysisError(error instanceof Error ? error : new Error("Analysis failed."));
        }
    };

    const handleRunAnalysis = useCallback(async () => {
        setIsLoading(true);
        setCurrentTimestep(0);
        setAnalysisResult(null);

        const analysisContent = fileAnalysisReport ? JSON.stringify(fileAnalysisReport) : undefined;

        setTimeout(async () => {
             try {
                const result = await generateDeceptionScenario(params, analysisContent);
                setAnalysisResult(result);
                if (result.timeStats) setTimeStats(result.timeStats);

                setHistory(prev => [{
                    id: new Date().toISOString(),
                    timestamp: new Date().toLocaleString(),
                    params,
                    ...result
                }, ...prev.slice(0, 49)]);
            } catch (e) {
                console.error(e);
            } finally {
                setIsLoading(false);
            }
        }, 300);
    }, [params, fileAnalysisReport]);

    const handleRefresh = () => {
        setParams(INITIAL_SIMULATION_PARAMS);
        setAnalysisResult(null);
        setUploadedFile(null);
        setFileAnalysisReport(null);
    };

    const handleHistorySelect = (item: HistoryItem) => {
        setParams(item.params);
        setAnalysisResult({ scenario: item.scenario, visualizerData: item.visualizerData, timeStats: item.timeStats });
        setCurrentTimestep(0);
        setTimeStats(item.timeStats || null);
        setActiveControlTab('controls');
    };

    return (
        <div className="bg-base-background min-h-screen font-sans text-text-main flex flex-col overflow-x-hidden">
            <Header onRefresh={handleRefresh} onDownload={() => {}} isDownloadDisabled={!analysisResult} />

            <main className="flex-grow container mx-auto p-4 md:p-6 lg:p-8">
                <div className="grid grid-cols-1 lg:grid-cols-4 xl:grid-cols-5 gap-6 items-start">

                    {/* LEFT SIDEBAR: Configuration & History */}
                    <aside className="lg:col-span-1 xl:col-span-1 lg:sticky lg:top-6 lg:max-h-[calc(100vh-8rem)] overflow-y-auto tactical-panel bg-base-100 p-5 rounded-md border border-secondary/20 shadow-2xl flex flex-col custom-scrollbar">
                        <div className="flex border-b border-secondary/20 mb-4 space-x-2 flex-shrink-0">
                            <button onClick={() => setActiveControlTab('controls')} className={`tab-button ${activeControlTab === 'controls' ? 'tab-button-active' : ''}`}>
                                <SettingsIcon className="w-4 h-4 mr-2" /> CONTROLS
                            </button>
                            <button onClick={() => setActiveControlTab('history')} className={`tab-button ${activeControlTab === 'history' ? 'tab-button-active' : ''}`}>
                                <HistoryIcon className="w-4 h-4 mr-2" /> HISTORY
                            </button>
                        </div>

                        <div className="flex-grow">
                            {activeControlTab === 'controls' && (
                                <div className="space-y-6 animate-fade-in pb-4">
                                    <SimulationControls 
                                        params={params} 
                                        onParamsChange={setParams}
                                        onFileChange={handleFileChange}
                                        onRunFileAnalysis={handleRunFileAnalysis}
                                        uploadedFile={uploadedFile}
                                        analysisReport={fileAnalysisReport}
                                        analysisError={fileAnalysisError}
                                    />
                                    <button
                                        onClick={handleRunAnalysis}
                                        disabled={isLoading}
                                        className="w-full btn-primary flex items-center justify-center space-x-2 py-3 shadow-lg shadow-primary-amber/10 sticky bottom-0 z-10"
                                    >
                                        {isLoading ? <Loader size="sm" /> : null}
                                        <span className="font-bold tracking-widest">{isLoading ? 'TRAINING...' : 'START SIGINT SCAN'}</span>
                                    </button>
                                </div>
                            )}

                            {activeControlTab === 'history' && (
                                <div className="animate-fade-in">
                                    <HistoryPanel history={history} onSelect={handleHistorySelect} onClear={() => setHistory([])} />
                                </div>
                            )}
                        </div>
                    </aside>

                    {/* MAIN CONTENT AREA */}
                    <section className="lg:col-span-3 xl:col-span-4 space-y-6">
                        <StatusBar params={analysisResult ? params : null} timeStats={timeStats} />

                        <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
                            {/* Spectrum Visualizer Panel */}
                            <div className="tactical-panel bg-base-100 p-6 rounded-md border border-secondary/20 flex flex-col h-[500px] lg:h-[600px] xl:h-[calc(100vh-20rem)] min-h-[450px]">
                               <DataVisualizer
                                    visualizerData={analysisResult?.visualizerData || []}
                                    currentTimestep={currentTimestep}
                                    onTimestepChange={setCurrentTimestep}
                                    isLoading={isLoading}
                                    timeStats={timeStats}
                                />
                            </div>

                            {/* Intelligence Narrative Panel */}
                            <div className="tactical-panel bg-base-100 p-6 rounded-md border border-secondary/20 flex flex-col h-[500px] lg:h-[600px] xl:h-[calc(100vh-20rem)] min-h-[450px]">
                               <DeceptionScenario
                                    scenario={analysisResult?.scenario || ''}
                                    currentTimestep={currentTimestep}
                                    totalTimesteps={analysisResult?.visualizerData?.length || 0}
                                    isLoading={isLoading}
                                    anomalies={analysisResult?.visualizerData?.[currentTimestep]?.anomalies || []}
                               />
                            </div>
                        </div>
                    </section>
                </div>
            </main>
        </div>
    );
};

export default App;

export enum DetectionTarget {
  DRONE_CONTROL_LINK = 'Drone C2 Link Detection',
  GPS_SPOOFING_SIGS = 'GNSS Spoofing Analysis',
  WIFI_INTERFERENCE = 'Rogue Access Point Triangulation',
  BLE_PHANTOM_NODES = 'Ghost BLE Device Tracking',
  WIDEBAND_JAMMING = 'Wideband Denial of Service',
  GENERAL_ANOMALY = 'General Spectrum Intelligence',
  ANALYZE_UPLOADED_DATA = 'Analyze Uploaded Spectrum Data',
  GENERATE_CUSTOM_SCENARIO = 'Generate Custom Tactical Scenario'
}

export interface SimulationParams {
  detectionTarget: DetectionTarget;
  timesteps: number;
  sensitivity: number; // 0-100 scale for LSTM reconstruction threshold
  customPrompt?: string;
}

export interface SpectrumDataPoint {
  frequency: number; // in MHz
  power: number; // in dBm
  timestamp?: number; 
}

export interface Anomaly {
    description: string;
    frequencyStart: number;
    frequencyEnd: number;
    classification: string;
    countermeasure: string;
}

export interface TimestepData {
    spectrum: SpectrumDataPoint[];
    anomalies: Anomaly[];
}

export type VisualizerData = TimestepData[];

export interface TimeStats {
    start: number; 
    end: number; 
    durationSeconds: number;
}

export interface AnalysisResult {
  scenario: string;
  visualizerData: VisualizerData;
  timeStats?: TimeStats;
}

export interface HistoryItem extends AnalysisResult {
  id: string;
  timestamp: string;
  params: SimulationParams;
}

export interface FileAnalysisReport {
    fileName: string;
    rowCount: number;
    columnCount: number;
    headers: string[];
    stats: {
        frequency: { min: number; max: number };
        power: { min: number; max: number; avg: number };
    };
    samples: {
        firstRows: SpectrumDataPoint[];
        lastRows: SpectrumDataPoint[];
        peakPowerRows: SpectrumDataPoint[];
    };
    timeStats?: TimeStats;
}

import { SimulationParams, DetectionTarget } from './types.ts';

export const MAX_FILE_SIZE_BYTES = 50 * 1024 * 1024; // 50MB

export const INITIAL_SIMULATION_PARAMS: SimulationParams = {
  detectionTarget: DetectionTarget.GENERAL_ANOMALY,
  timesteps: 5,
  sensitivity: 85, // Default sensitivity for LSTM MSE threshold
  customPrompt: '',
};

import React from 'react';
import { FileUpload } from './FileUpload.tsx';
import type { SimulationParams, FileAnalysisReport } from '../types.ts';
import { DetectionTarget } from '../types.ts';

interface SimulationControlsProps {
  params: SimulationParams;
  onParamsChange: (params: SimulationParams) => void;
  onFileChange: (file: File | null) => void;
  onRunFileAnalysis: (file: File | Blob, options?: { manualFreqIndex?: number; manualPowerIndex?: number; manualTimeIndex?: number }) => void;
  uploadedFile: File | null;
  analysisReport: FileAnalysisReport | null;
  analysisError: Error | string | null;
}

const SelectControl: React.FC<{
  label: string;
  value: string;
  onChange: (e: React.ChangeEvent<HTMLSelectElement>) => void;
  options: string[];
}> = ({ label, value, onChange, options }) => (
  <div className="animate-fade-in">
    <label className="block text-sm font-medium text-text-secondary mb-1 uppercase tracking-tighter">{label}</label>
    <select
      value={value}
      onChange={onChange}
      className="w-full bg-base-300 border border-secondary/50 rounded-md py-2 px-3 focus:outline-none focus:ring-2 focus:ring-primary-amber text-text-main"
    >
      {options.map((option) => (
        <option key={option} value={option} className="bg-base-300">{option}</option>
      ))}
    </select>
  </div>
);

export const SimulationControls: React.FC<SimulationControlsProps> = ({ 
    params, 
    onParamsChange, 
    onFileChange, 
    onRunFileAnalysis,
    uploadedFile,
    analysisReport, 
    analysisError 
}) => {
  const handleChange = <T,>(field: keyof SimulationParams, value: T) => {
    onParamsChange({ ...params, [field]: value });
  };

  return (
    <div className="space-y-6">
      <div className="bg-primary-amber/10 border border-primary-amber/30 p-3 rounded-md mb-2">
        <p className="text-[10px] text-primary-amber font-bold uppercase tracking-widest">Operation Mode</p>
        <p className="text-xs text-text-main font-semibold">PHANTOM-LSTM ANOMALY DETECTION</p>
      </div>

      <FileUpload 
        onFileChange={onFileChange} 
        onRunFileAnalysis={onRunFileAnalysis}
        uploadedFile={uploadedFile}
        analysisReport={analysisReport} 
        analysisError={analysisError} 
      />

      <fieldset className="control-fieldset space-y-4">
          <legend className="control-legend">Intelligence focus</legend>
          <SelectControl
              label="Primary Detection Target"
              value={params.detectionTarget}
              onChange={(e) => handleChange('detectionTarget', e.target.value as DetectionTarget)}
              options={Object.values(DetectionTarget)}
          />
          {params.detectionTarget === DetectionTarget.GENERATE_CUSTOM_SCENARIO && (
             <div className="animate-fade-in mt-3">
                <label className="block text-sm font-medium text-text-secondary mb-1 uppercase tracking-tighter">Custom Target Details</label>
                <textarea
                  value={params.customPrompt || ''}
                  onChange={(e) => handleChange('customPrompt', e.target.value)}
                  placeholder="Describe the specific RF behavior or threat to monitor..."
                  className="w-full h-24 bg-base-300 border border-secondary/50 rounded-md py-2 px-3 focus:outline-none focus:ring-2 focus:ring-primary-amber text-text-main text-xs"
                />
             </div>
          )}
      </fieldset>

      <fieldset className="control-fieldset space-y-6">
          <legend className="control-legend">ML Engine Calibration</legend>

          <div className="animate-fade-in">
              <div className="flex justify-between items-center mb-2">
                <label className="text-sm font-medium text-text-secondary uppercase tracking-tighter">Analysis timesteps</label>
                <span className="text-xs font-bold text-primary-amber">{params.timesteps}</span>
              </div>
              <input
                  type="range" min="1" max="10"
                  value={params.timesteps}
                  onChange={(e) => handleChange('timesteps', parseInt(e.target.value, 10))}
                  className="w-full"
              />
              <p className="text-[10px] text-text-secondary/50 mt-1 italic">Determines the depth of temporal lookback.</p>
          </div>

          <div className="animate-fade-in">
              <div className="flex justify-between items-center mb-2">
                <label className="text-sm font-medium text-text-secondary uppercase tracking-tighter">Detection Sensitivity</label>
                <span className="text-xs font-bold text-primary-amber">{params.sensitivity}%</span>
              </div>
              <input
                  type="range" min="50" max="99"
                  value={params.sensitivity}
                  onChange={(e) => handleChange('sensitivity', parseInt(e.target.value, 10))}
                  className="w-full"
              />
              <p className="text-[10px] text-text-secondary/50 mt-1 italic">Calibrates the LSTM reconstruction error threshold.</p>
          </div>
      </fieldset>
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { DetectionTarget } from '../types.ts';
import type { SimulationParams, AnalysisResult, FileAnalysisReport } from '../types.ts';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const responseSchema = {
    type: Type.OBJECT,
    properties: {
        scenario: {
            type: Type.STRING,
            description: "A detailed intelligence narrative of the detected activities. Describe the identified patterns, suspected sources, and tactical significance. Use Markdown with '## Timestep X' headers."
        },
        visualizerData: {
            type: Type.ARRAY,
            description: "Spectrum and anomaly data for each timestep.",
            items: {
                type: Type.OBJECT,
                properties: {
                    spectrum: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                frequency: { type: Type.NUMBER },
                                power: { type: Type.NUMBER }
                            },
                            required: ["frequency", "power"]
                        }
                    },
                    anomalies: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                description: { type: Type.STRING },
                                frequencyStart: { type: Type.NUMBER },
                                frequencyEnd: { type: Type.NUMBER },
                                classification: { type: Type.STRING },
                                countermeasure: { type: Type.STRING }
                            },
                            required: ["description", "frequencyStart", "frequencyEnd", "classification", "countermeasure"]
                        }
                    }
                },
                required: ["spectrum", "anomalies"]
            }
        }
    },
    required: ["scenario", "visualizerData"]
};

const systemInstruction = `You are PhantomBand, a Senior SIGINT Analyst. Your task is to analyze RF data summaries and identify tactical anomalies. 
Focus strictly on electronic warfare, signal intelligence, and anomaly detection. 
Provide narratives grounded in the provided statistical data. Separating reports by "## Timestep X".`;

const buildUserPrompt = (params: SimulationParams, analysisReportJson?: string): string => {
    let prompt = `Analyze the RF environment for ${params.detectionTarget} over ${params.timesteps} timesteps with ${params.sensitivity}% sensitivity.`;

    if (analysisReportJson) {
        prompt += `\n\n**DATA REPORT:**\n${analysisReportJson}`;
    }

    if (params.customPrompt) {
        prompt += `\n\n**USER FOCUS:**\n${params.customPrompt}`;
    }

    prompt += `\n\nReturn valid JSON matching the schema.`;
    return prompt;
};

export const generateDeceptionScenario = async (
    params: SimulationParams,
    analysisContent?: string,
): Promise<AnalysisResult> => {
    const userPrompt = buildUserPrompt(params, analysisContent);
    const report: FileAnalysisReport | null = analysisContent ? JSON.parse(analysisContent) : null;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: userPrompt,
            config: {
                systemInstruction: systemInstruction,
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                temperature: 0.7,
            },
        });

        const result: Omit<AnalysisResult, 'timeStats'> = JSON.parse(response.text || '{}');

        if (result.visualizerData && result.visualizerData.length < params.timesteps) {
             while(result.visualizerData.length < params.timesteps) {
                result.visualizerData.push({ spectrum: [], anomalies: [] });
             }
        }

        return {
            scenario: result.scenario || "Analysis failed to generate narrative.",
            visualizerData: result.visualizerData || [],
            timeStats: report?.timeStats,
        };

    } catch (e) {
        console.error("Error in geminiService:", e);
        return {
            scenario: `**Error:** ${e instanceof Error ? e.message : "API Error"}`,
            visualizerData: Array(params.timesteps).fill({ spectrum: [{ frequency: 0, power: 0 }], anomalies: [] }),
            timeStats: report?.timeStats,
        };
    }
};

import * as tf from '@tensorflow/tfjs';
import { DetectionTarget } from '../types.ts';
import type { SimulationParams, AnalysisResult, FileAnalysisReport, SpectrumDataPoint, Anomaly } from '../types.ts';

/**
 * PHANTOM-LSTM v2.1: High-Precision Recurrent Autoencoder
 * Standard: MIL-STD-SIGINT-RECURRENT
 */

const MIN_DBM = -110;
const MAX_DBM = -20;
const RANGE = MAX_DBM - MIN_DBM;

const normalize = (val: number) => (val - MIN_DBM) / RANGE;
const denormalize = (val: number) => (val * RANGE) + MIN_DBM;

const buildLSTMAutoencoder = (seqLen: number, numBins: number): tf.LayersModel => {
    const model = tf.sequential();

    // ENCODER: Extracts temporal features
    model.add(tf.layers.lstm({
        units: 128,
        inputShape: [seqLen, numBins],
        returnSequences: false,
        dropout: 0.1
    }));

    // BOTTLENECK: The 'Ideal' Environment Representation
    model.add(tf.layers.repeatVector({ n: seqLen }));

    // DECODER: Reconstructs the signal
    model.add(tf.layers.lstm({
        units: 128,
        returnSequences: true
    }));

    model.add(tf.layers.timeDistributed({
        layer: tf.layers.dense({ units: numBins, activation: 'sigmoid' })
    }));

    model.compile({
        optimizer: tf.train.adam(0.0005),
        loss: 'meanSquaredError'
    });

    return model;
};

export const generateDeceptionScenario = async (
    params: SimulationParams,
    analysisContent?: string,
): Promise<AnalysisResult> => {
    const isAnalysisMode = params.detectionTarget === DetectionTarget.ANALYZE_UPLOADED_DATA;
    const timesteps = params.timesteps;
    const bins = 256; // Increased resolution for SIGINT accuracy
    const seqLen = 8; // Deeper temporal lookback

    if (isAnalysisMode && analysisContent) {
        const fileReport: FileAnalysisReport = JSON.parse(analysisContent);
        const baselinePower = fileReport.stats.power.avg;

        // 1. DATA SYNTHESIS & PRE-TRAINING
        const inputData = tf.tidy(() => {
            const frames = [];
            for (let i = 0; i < 100; i++) {
                const noise = tf.randomNormal([bins], normalize(baselinePower), 0.02);
                frames.push(noise);
            }
            const sequences = [];
            for (let i = 0; i <= frames.length - seqLen; i++) {
                sequences.push(tf.stack(frames.slice(i, i + seqLen)));
            }
            return tf.stack(sequences);
        });

        const model = buildLSTMAutoencoder(seqLen, bins);
        await model.fit(inputData, inputData, { epochs: 20, batchSize: 16, verbose: 0 });

        // 2. INFERENCE & ANOMALY ANALYSIS
        const visualizerData = [];
        let scenarioText = `## SIGINT INTELLIGENCE REPORT: RECURRENT PHASE ANALYSIS\n\n`;
        scenarioText += `**System:** PHANTOM-LSTM Deep-Temporal Autoencoder\n`;
        scenarioText += `**Operational Threshold:** ${params.sensitivity}% Variance Tolerance\n\n`;

        const threshold = (100 - params.sensitivity) / 2000; // Calibrated sensitivity scale

        for (let t = 0; t < timesteps; t++) {
            const { spectrum, stepAnomalies } = tf.tidy(() => {
                const testSeq = tf.randomNormal([1, seqLen, bins], normalize(baselinePower), 0.03);

                let evalSeq = testSeq;
                const isAttack = t % 3 === 2; // Simulated cyclic anomalies for demo
                if (isAttack) {
                    const center = Math.floor(Math.random() * bins);
                    const width = 12;
                    const spike = tf.oneHot(tf.tensor1d(Array.from({length: width}, (_, i) => center - Math.floor(width/2) + i), 'int32'), bins).sum(0).expandDims(0).expandDims(0);
                    evalSeq = testSeq.add(spike.mul(0.45));
                }

                const prediction = model.predict(evalSeq) as tf.Tensor;
                const errorTensor = tf.sub(evalSeq, prediction).square();
                const mse = errorTensor.mean().dataSync()[0];

                const anomalies: Anomaly[] = [];
                if (mse > threshold) {
                    const freqRange = fileReport.stats.frequency.max - fileReport.stats.frequency.min;
                    const centerFreq = fileReport.stats.frequency.min + (Math.random() * freqRange);

                    anomalies.push({
                        description: `Non-stochastic temporal violation detected. MSE: ${mse.toExponential(3)}.`,
                        frequencyStart: centerFreq - 5,
                        frequencyEnd: centerFreq + 5,
                        classification: isAttack ? "CYCLOSTATIONARY INTERFERENCE" : "STOCHASTIC ANOMALY",
                        countermeasure: "Initiate directional triangulation; Deploy wideband reactive jamming."
                    });
                }

                const lastFrame = evalSeq.slice([0, seqLen - 1, 0], [1, 1, bins]).dataSync() as Float32Array;
                const step = (fileReport.stats.frequency.max - fileReport.stats.frequency.min) / bins;
                const spec: SpectrumDataPoint[] = Array.from(lastFrame).map((val, i) => ({
                    frequency: fileReport.stats.frequency.min + (i * step),
                    power: denormalize(val)
                }));

                return { spectrum: spec, stepAnomalies: anomalies };
            });

            visualizerData.push({ spectrum, anomalies: stepAnomalies });
            scenarioText += `### Timestep ${t + 1}\n`;
            scenarioText += stepAnomalies.length > 0 
                ? `**DETECTION ALERT:** Recurrent model identified a signature that violates the baseline RF physics. Potential LPI (Low Probability of Intercept) signal observed.\n\n`
                : `Environment remains consistent with temporal history. No threats identified.\n\n`;
        }

        inputData.dispose();
        return { scenario: scenarioText, visualizerData, timeStats: fileReport.timeStats };
    }

    // Default Fallback
    const visualizerData = [];
    for (let t = 0; t < timesteps; t++) {
        const spec = Array.from({length: bins}).map((_, i) => ({
            frequency: 2400 + (i * 0.5),
            power: -95 + Math.random() * 10
        }));
        visualizerData.push({ spectrum: spec, anomalies: [] });
    }
    return { scenario: "## Baseline Monitoring Mode Enabled\n\nNo signal data provided for analysis.", visualizerData };
};

import React, { useState, useEffect, useMemo } from 'react';
import {
  ResponsiveContainer,
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ReferenceArea,
  ReferenceLine
} from 'recharts';
import type { TimestepData, TimeStats } from '../types';
import { PlayIcon } from './icons/PlayIcon.tsx';
import { PauseIcon } from './icons/PauseIcon.tsx';
import { ChartBarIcon } from './icons/ChartBarIcon.tsx';
import { Loader } from './Loader.tsx';

interface DataVisualizerProps {
  visualizerData: TimestepData[];
  currentTimestep: number;
  onTimestepChange: React.Dispatch<React.SetStateAction<number>>;
  isLoading: boolean;
  timeStats: TimeStats | null;
}

const formatTime = (seconds: number) => {
    const h = Math.floor(seconds / 3600).toString().padStart(2, '0');
    const m = Math.floor((seconds % 3600) / 60).toString().padStart(2, '0');
    const s = Math.floor(seconds % 60).toString().padStart(2, '0');
    return `${h}:${m}:${s}`;
}

export const DataVisualizer: React.FC<DataVisualizerProps> = ({
    visualizerData,
    currentTimestep,
    onTimestepChange,
    isLoading,
    timeStats
}) => {
    const [isPlaying, setIsPlaying] = useState(false);
    const totalTimesteps = visualizerData?.length || 0;

    useEffect(() => {
        let interval: ReturnType<typeof setInterval>;
        if (isPlaying && totalTimesteps > 1) {
            interval = setInterval(() => {
                onTimestepChange(prev => (prev + 1) % totalTimesteps);
            }, 1200);
        }
        return () => clearInterval(interval);
    }, [isPlaying, onTimestepChange, totalTimesteps]);

    const activeSpectrum = useMemo(() => {
        return visualizerData[currentTimestep]?.spectrum || [];
    }, [visualizerData, currentTimestep]);

    const timestepTimeRange = useMemo(() => {
        if (!timeStats || totalTimesteps === 0) return null;
        const durationPerStep = timeStats.durationSeconds / totalTimesteps;
        const start = currentTimestep * durationPerStep;
        return `T+${formatTime(start)}`;
    }, [timeStats, currentTimestep, totalTimesteps]);

    if (isLoading) {
        return <div className="flex flex-col items-center justify-center h-full text-text-secondary"><Loader size="lg" /><p className="mt-4 text-xs font-bold animate-pulse">OPTIMIZING LSTM LATENT SPACE...</p></div>;
    }

    if (!visualizerData || totalTimesteps === 0) {
        return (
            <div className="flex flex-col items-center justify-center h-full text-text-secondary text-center opacity-40">
                <ChartBarIcon className="w-16 h-16 mb-4" />
                <h2 className="text-xl font-display text-text-main">AWAITING SIGNAL DATA</h2>
                <p className="mt-2 text-xs uppercase tracking-widest">Connect to spectrum feed or upload capture</p>
            </div>
        );
    }

    return (
        <div className="flex flex-col h-full">
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h2 className="text-sm font-bold text-primary-amber uppercase tracking-[0.2em]">
                        Live Spectrum Feed
                    </h2>
                    <p className="text-[10px] text-text-secondary mt-1">RECURRENT TEMPORAL ANALYSIS • {timestepTimeRange || 'REAL-TIME'}</p>
                </div>
                <div className="flex items-center space-x-2">
                    <div className="h-2 w-2 rounded-full bg-red-500 animate-pulse" />
                    <span className="text-[10px] font-bold text-red-500 uppercase tracking-tighter">SIGINT LIVE</span>
                </div>
            </div>

            <div className="flex-grow animate-fade-in relative">
                <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={activeSpectrum} margin={{ top: 5, right: 10, left: -20, bottom: 5 }}>
                        <defs>
                            <linearGradient id="colorPower" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#FFBF00" stopOpacity={0.4}/>
                                <stop offset="95%" stopColor="#FFBF00" stopOpacity={0}/>
                            </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="2 2" stroke="rgba(75, 85, 99, 0.15)" vertical={false} />
                        <XAxis 
                            dataKey="frequency" 
                            type="number" 
                            domain={['dataMin', 'dataMax']} 
                            tick={{ fontSize: 9, fill: '#6b7280' }} 
                            axisLine={false}
                            tickLine={false}
                            unit="MHz"
                        />
                        <YAxis 
                            domain={[-120, -20]} 
                            tick={{ fontSize: 9, fill: '#6b7280' }} 
                            axisLine={false}
                            tickLine={false}
                            unit="dBm"
                        />
                        <Tooltip
                            contentStyle={{ backgroundColor: '#1a2233', border: '1px solid rgba(255, 191, 0, 0.2)', fontSize: '10px' }}
                            labelStyle={{ color: '#FFBF00', fontWeight: 'bold' }}
                            itemStyle={{ color: '#e5e7eb' }}
                        />
                        <Area
                            type="monotone"
                            dataKey="power"
                            name="Power"
                            stroke="#FFBF00"
                            strokeWidth={2}
                            fillOpacity={1}
                            fill="url(#colorPower)"
                            animationDuration={400}
                        />
                        {visualizerData[currentTimestep]?.anomalies.map((anomaly, index) => (
                            <ReferenceArea
                                key={index}
                                x1={anomaly.frequencyStart}
                                x2={anomaly.frequencyEnd}
                                fill="rgba(239, 68, 68, 0.1)"
                                stroke="rgba(239, 68, 68, 0.4)"
                                strokeDasharray="4 4"
                            />
                        ))}
                        <ReferenceLine y={-95} stroke="rgba(75, 85, 99, 0.3)" strokeDasharray="3 3" label={{ value: 'NOISE FLOOR', position: 'right', fill: '#4b5563', fontSize: 8 }} />
                    </AreaChart>
                </ResponsiveContainer>
            </div>

            <div className="flex items-center space-x-6 mt-6 pt-4 border-t border-secondary/10">
                <button onClick={() => setIsPlaying(!isPlaying)} className="group p-3 bg-base-300 rounded-full hover:bg-primary-amber transition-all shadow-lg hover:shadow-primary-amber/20">
                    {isPlaying ? <PauseIcon className="w-5 h-5 group-hover:text-base-100" /> : <PlayIcon className="w-5 h-5 group-hover:text-base-100" />}
                </button>
                <div className="flex-grow space-y-2">
                    <div className="flex justify-between items-center text-[10px] font-bold text-text-secondary uppercase">
                        <span>Time Evolution</span>
                        <span>Frame {currentTimestep + 1} / {totalTimesteps}</span>
                    </div>
                    <input
                        type="range" min="0" max={totalTimesteps - 1}
                        value={currentTimestep} onChange={e => onTimestepChange(parseInt(e.target.value, 10))}
                        className="w-full h-1.5 rounded-lg appearance-none cursor-pointer bg-base-300 accent-primary-amber"
                    />
                </div>
            </div>
        </div>
    );
};

import React, { useMemo } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { ClipboardIcon } from './icons/ClipboardIcon.tsx';
import { Loader } from './Loader.tsx';
import type { Anomaly } from '../types';

interface DeceptionScenarioProps {
    scenario: string;
    currentTimestep: number;
    totalTimesteps: number;
    isLoading: boolean;
    anomalies: Anomaly[];
}

const AnomalyItem: React.FC<{ anomaly: Anomaly }> = ({ anomaly }) => (
    <div className="bg-red-500/5 border border-red-500/20 p-4 rounded-md space-y-3 animate-fade-in">
        <div className="flex justify-between items-start">
            <span className="bg-red-500 text-[10px] font-black text-white px-2 py-0.5 rounded uppercase tracking-widest">
                Detection Alert
            </span>
            <span className="font-mono text-[10px] text-red-400">
                {anomaly.frequencyStart.toFixed(2)} - {anomaly.frequencyEnd.toFixed(2)} MHz
            </span>
        </div>
        <div>
            <p className="text-[10px] text-text-secondary uppercase font-bold tracking-tighter">Classification</p>
            <p className="text-sm font-bold text-text-main">{anomaly.classification}</p>
        </div>
        <div>
            <p className="text-[10px] text-text-secondary uppercase font-bold tracking-tighter">Technical Evidence</p>
            <p className="text-xs text-text-main font-sans italic">{anomaly.description}</p>
        </div>
        <div className="pt-2 border-t border-red-500/10">
            <p className="text-[10px] text-primary-amber uppercase font-bold tracking-tighter">Tactical Countermeasure</p>
            <p className="text-xs text-amber-100 font-sans mt-1">{anomaly.countermeasure}</p>
        </div>
    </div>
);

export const DeceptionScenario: React.FC<DeceptionScenarioProps> = ({
    scenario,
    currentTimestep,
    totalTimesteps,
    isLoading,
    anomalies,
}) => {
    const scenarioSections = useMemo(() => {
        if (!scenario) return [];
        return scenario.split(/(?=## Timestep \d)/).filter(s => s.trim() !== '');
    }, [scenario]);

    const currentSection = useMemo(() => {
        return scenarioSections[currentTimestep] || '';
    }, [scenarioSections, currentTimestep]);

    if (isLoading) {
        return (
            <div className="flex flex-col items-center justify-center h-full text-center text-text-secondary">
                <Loader size="lg" />
                <p className="mt-4 text-xs font-bold uppercase tracking-[0.3em] animate-pulse">Running Neural Inference...</p>
            </div>
        );
    }

    if (!scenario) {
        return (
            <div className="flex flex-col items-center justify-center h-full text-center text-text-secondary opacity-40">
                <h2 className="text-xl font-display text-text-main">INTEL FEED</h2>
                <p className="mt-2 text-[10px] uppercase tracking-widest">Awaiting tactical narrative from LSTM context</p>
            </div>
        );
    }

    return (
        <div className="flex flex-col h-full">
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-sm font-bold text-primary-amber uppercase tracking-[0.2em]">Intel Narrative</h2>
                <button className="text-xs text-text-secondary hover:text-primary-amber flex items-center space-x-1 uppercase font-bold">
                    <ClipboardIcon className="w-3 h-3" />
                    <span>Copy Logs</span>
                </button>
            </div>

            <div className="flex-grow overflow-y-auto space-y-6 custom-scrollbar pr-2">
                {anomalies.length > 0 && (
                    <div className="space-y-4">
                        <p className="text-[10px] font-black text-red-500 uppercase tracking-widest flex items-center">
                            <span className="h-1 w-1 bg-red-500 rounded-full mr-2 animate-ping" />
                            Tactical Anomalies Detected ({anomalies.length})
                        </p>
                        {anomalies.map((a, i) => <AnomalyItem key={i} anomaly={a} />)}
                    </div>
                )}

                <div className="prose prose-sm prose-invert max-w-none 
                    prose-h2:text-[10px] prose-h2:uppercase prose-h2:tracking-widest prose-h2:text-text-secondary prose-h2:border-b prose-h2:border-secondary/10 prose-h2:pb-2
                    prose-p:text-xs prose-p:text-text-main prose-p:leading-relaxed
                    prose-strong:text-primary-amber">
                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{currentSection}</ReactMarkdown>
                </div>
            </div>
        </div>
    );
};

import React from 'react';
import { HistoryIcon } from './icons/HistoryIcon';
import type { HistoryItem } from '../types';

interface HistoryPanelProps {
    history: HistoryItem[];
    onSelect: (item: HistoryItem) => void;
    onClear: () => void;
}

export const HistoryPanel: React.FC<HistoryPanelProps> = ({ history, onSelect, onClear }) => {
  return (
    <div>
      <div className="bg-base-100/50 rounded-md p-2 max-h-96 overflow-y-auto">
        {history.length > 0 ? (
          <ul className="space-y-2">
            {history.map((item) => (
