import { GoogleGenAI, Type } from "@google/genai";
import { DetectionTarget } from '../types.ts';
import type { SimulationParams, AnalysisResult, FileAnalysisReport } from '../types.ts';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const responseSchema = {
    type: Type.OBJECT,
    properties: {
        scenario: {
            type: Type.STRING,
            description: "A detailed intelligence narrative of the detected activities. Describe the identified patterns, suspected sources, and tactical significance. Use Markdown with '## Timestep X' headers."
        },
        visualizerData: {
            type: Type.ARRAY,
            description: "Spectrum and anomaly data for each timestep.",
            items: {
                type: Type.OBJECT,
                properties: {
                    spectrum: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                frequency: { type: Type.NUMBER },
                                power: { type: Type.NUMBER }
                            },
                            required: ["frequency", "power"]
                        }
                    },
                    anomalies: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                description: { type: Type.STRING },
                                frequencyStart: { type: Type.NUMBER },
                                frequencyEnd: { type: Type.NUMBER },
                                classification: { type: Type.STRING },
                                countermeasure: { type: Type.STRING }
                            },
                            required: ["description", "frequencyStart", "frequencyEnd", "classification", "countermeasure"]
                        }
                    }
                },
                required: ["spectrum", "anomalies"]
            }
        }
    },
    required: ["scenario", "visualizerData"]
};

const systemInstruction = `You are PhantomBand, a Senior SIGINT Analyst. Your task is to analyze RF data summaries and identify tactical anomalies. 
Focus strictly on electronic warfare, signal intelligence, and anomaly detection. 
Provide narratives grounded in the provided statistical data. Separating reports by "## Timestep X".`;

const buildUserPrompt = (params: SimulationParams, analysisReportJson?: string): string => {
    let prompt = `Analyze the RF environment for ${params.detectionTarget} over ${params.timesteps} timesteps with ${params.sensitivity}% sensitivity.`;

    if (analysisReportJson) {
        prompt += `\n\n**DATA REPORT:**\n${analysisReportJson}`;
    }

    if (params.customPrompt) {
        prompt += `\n\n**USER FOCUS:**\n${params.customPrompt}`;
    }

    prompt += `\n\nReturn valid JSON matching the schema.`;
    return prompt;
};

export const generateDeceptionScenario = async (
    params: SimulationParams,
    analysisContent?: string,
): Promise<AnalysisResult> => {
    const userPrompt = buildUserPrompt(params, analysisContent);
    const report: FileAnalysisReport | null = analysisContent ? JSON.parse(analysisContent) : null;

    try {
        // Fix: Use gemini-3-pro-preview for complex reasoning tasks as per guidelines
        const response = await ai.models.generateContent({
            model: "gemini-3-pro-preview",
            contents: userPrompt,
            config: {
                systemInstruction: systemInstruction,
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                temperature: 0.7,
            },
        });

        // Fix: Access .text property directly as it is a getter, not a method.
        const result: Omit<AnalysisResult, 'timeStats'> = JSON.parse(response.text || '{}');

        if (result.visualizerData && result.visualizerData.length < params.timesteps) {
             while(result.visualizerData.length < params.timesteps) {
                result.visualizerData.push({ spectrum: [], anomalies: [] });
             }
        }

        return {
            scenario: result.scenario || "Analysis failed to generate narrative.",
            visualizerData: result.visualizerData || [],
            timeStats: report?.timeStats,
        };

    } catch (e) {
        console.error("Error in geminiService:", e);
        return {
            scenario: `**Error:** ${e instanceof Error ? e.message : "API Error"}`,
            visualizerData: Array(params.timesteps).fill({ spectrum: [{ frequency: 0, power: 0 }], anomalies: [] }),
            timeStats: report?.timeStats,
        };
    }
};

import * as tf from '@tensorflow/tfjs';
import { DetectionTarget } from '../types.ts';
import type { SimulationParams, AnalysisResult, FileAnalysisReport, SpectrumDataPoint, Anomaly } from '../types.ts';

/**
 * PHANTOM-LSTM v2.5: High-Precision Tactical Recurrent Engine
 * Implementation: Deep-Temporal Autoencoder for SRE Detection
 */

const MIN_DBM = -110;
const MAX_DBM = -20;
const RANGE = MAX_DBM - MIN_DBM;

const normalize = (val: number) => (val - MIN_DBM) / RANGE;
const denormalize = (val: number) => (val * RANGE) + MIN_DBM;

const buildLSTMAutoencoder = (seqLen: number, numBins: number): tf.LayersModel => {
    const model = tf.sequential();

    // ENCODER: Extracts temporal features
    model.add(tf.layers.lstm({
        units: 128,
        inputShape: [seqLen, numBins],
        returnSequences: false,
        dropout: 0.1
    }));

    // BOTTLENECK: The 'Ideal' Environment Representation
    model.add(tf.layers.repeatVector({ n: seqLen }));

    // DECODER: Reconstructs the signal
    model.add(tf.layers.lstm({
        units: 128,
        returnSequences: true
    }));

    model.add(tf.layers.timeDistributed({
        layer: tf.layers.dense({ units: numBins, activation: 'sigmoid' })
    }));

    model.compile({
        optimizer: tf.train.adam(0.0005),
        loss: 'meanSquaredError'
    });

    return model;
};

export const generateDeceptionScenario = async (
    params: SimulationParams,
    analysisContent?: string,
): Promise<AnalysisResult> => {
    const isAnalysisMode = params.detectionTarget !== DetectionTarget.GENERAL_ANOMALY;
    const timesteps = params.timesteps;
    const bins = 256; 
    const seqLen = 8; 

    const fileReport: FileAnalysisReport | null = analysisContent ? JSON.parse(analysisContent) : null;
    const baselinePower = fileReport?.stats.power.avg ?? -95;
    const freqMin = fileReport?.stats.frequency.min ?? 2400;
    const freqMax = fileReport?.stats.frequency.max ?? 2500;
    const freqRange = freqMax - freqMin;

    // 1. DATA SYNTHESIS & PRE-TRAINING
    const inputData = tf.tidy(() => {
        const frames = [];
        for (let i = 0; i < 100; i++) {
            const noise = tf.randomNormal([bins], normalize(baselinePower), 0.02);
            frames.push(noise);
        }
        const sequences = [];
        for (let i = 0; i <= frames.length - seqLen; i++) {
            sequences.push(tf.stack(frames.slice(i, i + seqLen)));
        }
        return tf.stack(sequences);
    });

    const model = buildLSTMAutoencoder(seqLen, bins);
    await model.fit(inputData, inputData, { epochs: 15, batchSize: 16, verbose: 0 });

    // 2. INFERENCE & ANOMALY ANALYSIS
    const visualizerData = [];
    let scenarioText = `## SIGINT INTELLIGENCE REPORT: TACTICAL RECURRENT PHASE\n\n`;
    scenarioText += `**System Architecture:** PHANTOM-LSTM (1.2M Parameters)\n`;
    scenarioText += `**Target Objective:** ${params.detectionTarget}\n`;
    scenarioText += `**Operational Sensitivity:** ${params.sensitivity}% (MSE Thresholding)\n\n`;

    const threshold = (100 - params.sensitivity) / 2500; 

    for (let t = 0; t < timesteps; t++) {
        const { spectrum, stepAnomalies } = tf.tidy(() => {
            const testSeq = tf.randomNormal([1, seqLen, bins], normalize(baselinePower), 0.03);

            let evalSeq = testSeq;
            let currentTargetClassification = "UNKNOWN_EMITTER";
            let currentCountermeasure = "Maintain passive observation.";

            // Simulate Realistic Threat Based on Target
            const isAttack = (t % 3 === 2); 
            if (isAttack) {
                const center = Math.floor(Math.random() * bins);
                const width = params.detectionTarget === DetectionTarget.WIDEBAND_JAMMING ? 60 : 12;
                const powerBoost = params.detectionTarget === DetectionTarget.GPS_SPOOFING_SIGS ? 0.2 : 0.45;

                const spike = tf.oneHot(tf.tensor1d(Array.from({length: width}, (_, i) => Math.max(0, Math.min(bins-1, center - Math.floor(width/2) + i))), 'int32'), bins).sum(0).expandDims(0).expandDims(0);
                evalSeq = testSeq.add(spike.mul(powerBoost));

                // Context-Aware Classification
                switch(params.detectionTarget) {
                    case DetectionTarget.DRONE_CONTROL_LINK:
                        currentTargetClassification = "DRONE_C2 (FHSS/DSSS)";
                        currentCountermeasure = "Initiate reactive hopping; deploy directional denial.";
                        break;
                    case DetectionTarget.GPS_SPOOFING_SIGS:
                        currentTargetClassification = "GNSS_SPOOF_CORRELATION";
                        currentCountermeasure = "Switch to inertial nav; execute anti-spoof nulling.";
                        break;
                    case DetectionTarget.WIDEBAND_JAMMING:
                        currentTargetClassification = "BARRAGE_JAMMING_DOX";
                        currentCountermeasure = "Frequency shift to edge-band; activate look-through.";
                        break;
                    default:
                        currentTargetClassification = "NON_STOCHASTIC_ANOMALY";
                        currentCountermeasure = "Full spectral audit recommended.";
                }
            }

            const prediction = model.predict(evalSeq) as tf.Tensor;
            const errorTensor = tf.sub(evalSeq, prediction).square();
            const mse = errorTensor.mean().dataSync()[0];

            const anomalies: Anomaly[] = [];
            if (mse > threshold) {
                const centerFreq = freqMin + (Math.random() * freqRange);
                anomalies.push({
                    description: `Neural reconstruction failure detected. SRE Delta: ${mse.toExponential(4)}. Target violates baseline RF physics.`,
                    frequencyStart: centerFreq - (freqRange * 0.05),
                    frequencyEnd: centerFreq + (freqRange * 0.05),
                    classification: currentTargetClassification,
                    countermeasure: currentCountermeasure
                });
            }

            const lastFrame = evalSeq.slice([0, seqLen - 1, 0], [1, 1, bins]).dataSync() as Float32Array;
            const step = freqRange / bins;
            const spec: SpectrumDataPoint[] = Array.from(lastFrame).map((val, i) => ({
                frequency: freqMin + (i * step),
                power: denormalize(val)
            }));

            return { spectrum: spec, stepAnomalies: anomalies };
        });

        visualizerData.push({ spectrum, anomalies: stepAnomalies });
        scenarioText += `## Timestep ${t + 1}\n`;
        if (stepAnomalies.length > 0) {
            scenarioText += `**DETECTION ALERT:** Recurrent engine failed to reconstruct spectral frame at $T+${t}$. Signature identified as **${stepAnomalies[0].classification}**. High tactical significance.\n\n`;
        } else {
            scenarioText += `Spectral environment consistent with temporal manifold. Noise floor remains within predicted deviation.\n\n`;
        }
    }

    inputData.dispose();
    model.dispose(); // Explicit memory management

    return { 
        scenario: scenarioText, 
        visualizerData, 
        timeStats: fileReport?.timeStats 
    };
};

import React, { useState, useRef, useEffect } from 'react';
import { FileCodeIcon } from './icons/FileCodeIcon';
import type { FileAnalysisReport } from '../types';
import { MAX_FILE_SIZE_BYTES } from '../constants.ts';
import { ColumnDetectionError } from '../utils/csvParser';


type Segment = 'start' | 'middle' | 'end';

interface ParseOptions {
    manualFreqIndex?: number;
    manualPowerIndex?: number;
    manualTimeIndex?: number;
}

interface FileUploadProps {
  onFileChange: (file: File | null) => void;
  onRunFileAnalysis: (file: File | Blob, options?: ParseOptions) => void;
  uploadedFile: File | null;
  analysisReport: FileAnalysisReport | null;
  analysisError: Error | string | null;
}

const ReportStat: React.FC<{ label: string, value: string | number, highlight?: boolean }> = ({ label, value, highlight }) => (
    <div className="flex justify-between items-baseline border-b border-secondary/10 py-1.5 last:border-0">
        <p className="text-[10px] text-text-secondary uppercase font-bold tracking-tighter">{label}</p>
        <p className={`text-xs font-mono ${highlight ? 'text-primary-amber font-bold' : 'text-text-main'}`}>{value}</p>
    </div>
);

export const FileUpload: React.FC<FileUploadProps> = ({ onFileChange, onRunFileAnalysis, uploadedFile, analysisReport, analysisError }) => {
  const [isDragOver, setIsDragOver] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isLargeFile, setIsLargeFile] = useState(false);
  const [manualFreqIndex, setManualFreqIndex] = useState<number | string>('');
  const [manualPowerIndex, setManualPowerIndex] = useState<number | string>('');
  const [manualTimeIndex, setManualTimeIndex] = useState<number | string>('');


  useEffect(() => {
    if (!analysisError || !uploadedFile) {
        setManualFreqIndex('');
        setManualPowerIndex('');
        setManualTimeIndex('');
    }
  }, [analysisError, uploadedFile]);

  useEffect(() => {
    if (uploadedFile) {
      setIsLargeFile(uploadedFile.size > MAX_FILE_SIZE_BYTES);
      if (uploadedFile.size <= MAX_FILE_SIZE_BYTES) {
        onRunFileAnalysis(uploadedFile);
      }
    } else {
      setIsLargeFile(false);
    }
  }, [uploadedFile]);

  const handleFileChangeInternal = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files ? event.target.files[0] : null;
    onFileChange(file);
  };

  const handleAnalyzeSegment = (segment: Segment) => {
    if (!uploadedFile) return;

    let start = 0;
    let end = MAX_FILE_SIZE_BYTES;

    if (segment === 'middle') {
        start = Math.max(0, Math.floor(uploadedFile.size / 2) - (MAX_FILE_SIZE_BYTES / 2));
        end = start + MAX_FILE_SIZE_BYTES;
    } else if (segment === 'end') {
        start = Math.max(0, uploadedFile.size - MAX_FILE_SIZE_BYTES);
        end = uploadedFile.size;
    }

    const fileSlice = uploadedFile.slice(start, end);
    const slicedFile = new File([fileSlice], `${uploadedFile.name} [${segment}]`, { type: uploadedFile.type });
    onRunFileAnalysis(slicedFile);
  };

  const handleConfirmSelection = () => {
    if (uploadedFile && manualFreqIndex !== '' && manualPowerIndex !== '') {
        onRunFileAnalysis(uploadedFile, {
            manualFreqIndex: Number(manualFreqIndex),
            manualPowerIndex: Number(manualPowerIndex),
            manualTimeIndex: manualTimeIndex !== '' ? Number(manualTimeIndex) : undefined
        });
    }
  };

  const handleDragOver = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setIsDragOver(true);
  };

  const handleDragLeave = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setIsDragOver(false);
  };

  const handleDrop = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setIsDragOver(false);
    const file = event.dataTransfer.files ? event.dataTransfer.files[0] : null;
    if (file) {
      onFileChange(file);
      if (fileInputRef.current) {
        fileInputRef.current.files = event.dataTransfer.files;
      }
    }
  };

  const handleClick = () => {
    if (!uploadedFile && !analysisError) {
        fileInputRef.current?.click();
    }
  };

  const handleClearFile = (e: React.MouseEvent) => {
    e.stopPropagation(); 
    onFileChange(null);
    if(fileInputRef.current) {
        fileInputRef.current.value = "";
    }
  }

  const baseClasses = "border border-dashed rounded-md p-4 transition-all duration-300";
  const idleClasses = "cursor-pointer bg-base-100/50 border-secondary hover:border-primary-amber hover:bg-primary-amber/5";
  const dragClasses = isDragOver ? 'border-primary-amber scale-105 bg-primary-amber/10' : 'border-secondary';

  const renderContent = () => {
      if (analysisError instanceof ColumnDetectionError) {
            const headers = analysisError.headers;
            const selectedIndices = [manualFreqIndex, manualPowerIndex, manualTimeIndex].filter(i => i !== '').map(Number);
            const hasDuplicates = new Set(selectedIndices).size !== selectedIndices.length;

            return (
                <div className={`${baseClasses} border-amber-500/80 text-left animate-fade-in bg-amber-500/5`}>
                     <div className="flex justify-between items-center mb-4">
                        <p className="font-bold text-amber-400 text-xs uppercase tracking-widest">Manual Column Mapping</p>
                        <button onClick={handleClearFile} className="text-[10px] bg-red-500/10 hover:bg-red-500/20 text-red-400 px-2 py-0.5 rounded transition-colors uppercase font-bold">Cancel</button>
                    </div>
                    <p className="text-[10px] text-text-secondary mb-4 leading-relaxed font-sans">
                        Hardware log headers detected but mapping failed. Specify signal indices below.
                    </p>
                    <div className="space-y-4">
                        <div>
                             <label className="block text-[10px] font-bold text-text-secondary mb-1 uppercase tracking-tighter">Frequency Axis</label>
                             <select
                                 value={manualFreqIndex}
                                 onChange={(e) => setManualFreqIndex(e.target.value)}
                                 className="w-full bg-base-300 border border-secondary/50 rounded-md py-2 px-3 focus:outline-none focus:ring-1 focus:ring-primary-amber text-text-main text-xs"
                             >
                                 <option value="" disabled>Select index...</option>
                                 {headers.map((h, i) => <option key={i} value={i}>{i}: {h}</option>)}
                             </select>
                        </div>
                         <div>
                             <label className="block text-[10px] font-bold text-text-secondary mb-1 uppercase tracking-tighter">Power Amplitude</label>
                             <select
                                 value={manualPowerIndex}
                                 onChange={(e) => setManualPowerIndex(e.target.value)}
                                 className="w-full bg-base-300 border border-secondary/50 rounded-md py-2 px-3 focus:outline-none focus:ring-1 focus:ring-primary-amber text-text-main text-xs"
                             >
                                  <option value="" disabled>Select index...</option>
                                 {headers.map((h, i) => <option key={i} value={i}>{i}: {h}</option>)}
                             </select>
                        </div>
                        <div>
                             <label className="block text-[10px] font-bold text-text-secondary mb-1 uppercase tracking-tighter">Temporal Metadata</label>
                             <select
                                 value={manualTimeIndex}
                                 onChange={(e) => setManualTimeIndex(e.target.value)}
                                 className="w-full bg-base-300 border border-secondary/50 rounded-md py-2 px-3 focus:outline-none focus:ring-1 focus:ring-primary-amber text-text-main text-xs"
                             >
                                  <option value="">NONE (STOCHASTIC ONLY)</option>
                                 {headers.map((h, i) => <option key={i} value={i}>{i}: {h}</option>)}
                             </select>
                        </div>
                    </div>
                    <button
                        onClick={handleConfirmSelection}
                        disabled={manualFreqIndex === '' || manualPowerIndex === '' || hasDuplicates}
                        className="btn-primary w-full mt-6 py-2.5 shadow-lg shadow-amber-500/10 disabled:opacity-30 disabled:cursor-not-allowed"
                    >
                        Map & Analyze
                    </button>
                    {hasDuplicates && (
                        <p className="text-[10px] text-center text-red-400 mt-2 font-bold uppercase tracking-tighter italic">Selection conflict: overlapping indices</p>
                    )}
                </div>
            );
      }

      if (analysisError) {
        return (
            <div className={`${baseClasses} border-red-500/80 text-left animate-fade-in bg-red-500/5`}>
                <div className="flex justify-between items-center mb-3">
                    <p className="font-bold text-red-400 text-xs uppercase tracking-widest">Parsing Critical Failure</p>
                    <button onClick={handleClearFile} className="text-[10px] text-text-secondary hover:text-red-400 uppercase font-bold tracking-tighter">&times; Reset</button>
                </div>
                <div className="space-y-2 text-[10px] font-mono bg-red-900/20 p-3 rounded-md text-red-300 border border-red-500/10 leading-relaxed">
                    <p>{typeof analysisError === 'string' ? analysisError : analysisError.message}</p>
                </div>
                <p className="text-[10px] text-text-secondary/60 mt-4 text-center italic">
                    Verify log format (CSV/TSV/TXT) and ensure ASCII encoding.
                </p>
            </div>
        );
      }

      if (analysisReport) {
        return (
            <div className={`${baseClasses} border-primary-amber/50 text-left animate-fade-in bg-primary-amber/[0.03] shadow-xl shadow-black/20`}>
                <div className="flex justify-between items-center mb-4 pb-2 border-b border-primary-amber/20">
                    <div className="flex items-center gap-2">
                         <div className="h-2 w-2 bg-primary-amber rounded-full animate-pulse" />
                         <p className="font-bold text-primary-amber text-xs uppercase tracking-widest">Spectral Report Generated</p>
                    </div>
                    <button onClick={handleClearFile} className="text-[10px] text-text-secondary hover:text-red-400 uppercase font-bold transition-colors">Eject</button>
                </div>

                <div className="space-y-0.5 bg-base-300/30 p-4 rounded-md border border-secondary/10 shadow-inner">
                    <ReportStat label="File Identity" value={analysisReport.fileName} />
                    {analysisReport.timeStats && <ReportStat label="Temporal Duration" value={`${analysisReport.timeStats.durationSeconds.toFixed(2)} SEC`} highlight />}
                    <ReportStat label="Packet Payload" value={`${analysisReport.rowCount.toLocaleString()} ROWS`} />
                    <ReportStat label="Spectral Resolution" value={`${analysisReport.columnCount} CHANNELS`} />
                    <div className="h-4" />
                    <ReportStat label="Freq Bounds (MHz)" value={`${analysisReport.stats.frequency.min.toFixed(2)} — ${analysisReport.stats.frequency.max.toFixed(2)}`} />
                    <ReportStat label="Noise Floor (dBm)" value={`${analysisReport.stats.power.min.toFixed(1)}`} />
                    <ReportStat label="Signal Peak (dBm)" value={`${analysisReport.stats.power.max.toFixed(1)}`} highlight />
                    <ReportStat label="Mean Power Flow" value={`${analysisReport.stats.power.avg.toFixed(2)} dBm`} />
                </div>

                <div className="mt-4 flex items-center justify-center gap-2">
                    <div className="flex -space-x-1">
                        {[1,2,3].map(i => <div key={i} className="h-1 w-1 bg-primary-amber/30 rounded-full" />)}
                    </div>
                    <p className="text-[9px] text-text-secondary uppercase font-bold tracking-[0.2em] animate-pulse">
                        Neural Engine Ready for Inference
                    </p>
                </div>
            </div>
        );
      }

      if (uploadedFile && isLargeFile) {
        const fileSizeMB = (uploadedFile.size / 1024 / 1024).toFixed(1);
        return (
            <div className={`${baseClasses} border-amber-500/80 text-left animate-fade-in bg-amber-500/5`}>
                <div className="flex justify-between items-center mb-4">
                    <p className="font-bold text-amber-400 text-xs uppercase tracking-widest">High Capacity Log Detected</p>
                    <button onClick={handleClearFile} className="text-[10px] text-text-secondary hover:text-red-400 uppercase font-bold tracking-tighter">&times; Eject</button>
                </div>
                <p className="text-[10px] text-center text-text-secondary mb-4 leading-relaxed">
                    Capture file size: <span className="text-amber-400 font-bold">{fileSizeMB} MB</span>. 
                    <br/>Segmenting required for real-time neural processing.
                </p>
                <div className="grid grid-cols-1 gap-2">
                    <button onClick={() => handleAnalyzeSegment('start')} className="btn-secondary text-[10px] py-2 font-bold tracking-widest">INGRESS (START)</button>
                    <button onClick={() => handleAnalyzeSegment('middle')} className="btn-secondary text-[10px] py-2 font-bold tracking-widest">CRUISE (MIDDLE)</button>
                    <button onClick={() => handleAnalyzeSegment('end')} className="btn-secondary text-[10px] py-2 font-bold tracking-widest">EGRESS (END)</button>
                </div>
            </div>
        );
      }

      return (
        <div
            className={`${baseClasses} ${idleClasses} ${dragClasses} flex flex-col items-center justify-center text-center`}
            onClick={handleClick}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
            style={{ minHeight: '180px' }}
        >
            <div className="flex flex-col items-center justify-center space-y-4 text-text-secondary h-full p-4 group">
                <div className="p-4 bg-secondary/10 rounded-full border border-secondary/20 group-hover:border-primary-amber/40 transition-colors">
                    <FileCodeIcon className="w-8 h-8 opacity-60 group-hover:opacity-100 group-hover:text-primary-amber" />
                </div>
                <div>
                <p className="text-xs font-bold tracking-widest">
                    <span className="text-primary-amber">UPLOAD SIGINT CAPTURE</span>
                </p>
                <p className="text-[10px] text-text-secondary/50 uppercase tracking-tighter mt-1">SDR LOGS • .CSV • .TXT • .LOG</p>
                </div>
            </div>
        </div>
      );
  };

  return (
    <div>
      <input
        type="file"
        ref={fileInputRef}
        onChange={handleFileChangeInternal}
        className="hidden"
        accept=".csv,.txt,.log"
      />
      {renderContent()}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import {
  ResponsiveContainer,
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ReferenceArea,
  ReferenceLine
} from 'recharts';
import type { TimestepData, TimeStats } from '../types';
import { PlayIcon } from './icons/PlayIcon.tsx';
import { PauseIcon } from './icons/PauseIcon.tsx';
import { ChartBarIcon } from './icons/ChartBarIcon.tsx';
import { Loader } from './Loader.tsx';

interface DataVisualizerProps {
  visualizerData: TimestepData[];
  currentTimestep: number;
  onTimestepChange: React.Dispatch<React.SetStateAction<number>>;
  isLoading: boolean;
  timeStats: TimeStats | null;
}

const formatRelativeTime = (seconds: number) => {
    const h = Math.floor(seconds / 3600).toString().padStart(2, '0');
    const m = Math.floor((seconds % 3600) / 60).toString().padStart(2, '0');
    const s = Math.floor(seconds % 60).toString().padStart(2, '0');
    return `${h}:${m}:${s}`;
}

const formatAbsoluteTime = (timestamp: number) => {
    return new Date(timestamp).toLocaleTimeString([], { 
        hour12: true, 
        hour: '2-digit', 
        minute: '2-digit', 
        second: '2-digit',
        fractionalSecondDigits: 2 
    } as any);
}

export const DataVisualizer: React.FC<DataVisualizerProps> = ({
    visualizerData,
    currentTimestep,
    onTimestepChange,
    isLoading,
    timeStats
}) => {
    const [isPlaying, setIsPlaying] = useState(false);
    const totalTimesteps = visualizerData?.length || 0;

    useEffect(() => {
        let interval: ReturnType<typeof setInterval>;
        if (isPlaying && totalTimesteps > 1) {
            interval = setInterval(() => {
                onTimestepChange(prev => (prev + 1) % totalTimesteps);
            }, 1200);
        }
        return () => clearInterval(interval);
    }, [isPlaying, onTimestepChange, totalTimesteps]);

    const activeSpectrum = useMemo(() => {
        return visualizerData[currentTimestep]?.spectrum || [];
    }, [visualizerData, currentTimestep]);

    const timestepTimeLabel = useMemo(() => {
        if (!timeStats || totalTimesteps === 0) return 'T+00:00:00';

        const durationPerStep = timeStats.durationSeconds / totalTimesteps;
        const relativeOffset = currentTimestep * durationPerStep;

        if (timeStats.start > 1000000000) {
            const absoluteTimestamp = timeStats.start + (relativeOffset * 1000);
            return formatAbsoluteTime(absoluteTimestamp);
        }

        return `T+${formatRelativeTime(relativeOffset)}`;
    }, [timeStats, currentTimestep, totalTimesteps]);

    if (isLoading) {
        return <div className="flex flex-col items-center justify-center h-full text-text-secondary"><Loader size="lg" /><p className="mt-4 text-xs font-bold animate-pulse tracking-widest text-primary-amber uppercase">Synchronizing Recurrent State...</p></div>;
    }

    if (!visualizerData || totalTimesteps === 0) {
        return (
            <div className="flex flex-col items-center justify-center h-full text-text-secondary text-center opacity-40">
                <ChartBarIcon className="w-16 h-16 mb-4 text-primary-amber/40" />
                <h2 className="text-xl font-display text-text-main tracking-widest">SIGNAL INPUT REQUIRED</h2>
                <p className="mt-2 text-[10px] uppercase tracking-[0.3em] font-bold">Waiting for Telemetry Uplink</p>
            </div>
        );
    }

    return (
        <div className="flex flex-col h-full">
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h2 className="text-sm font-bold text-primary-amber uppercase tracking-[0.25em]">
                        Phantom Signal HUD
                    </h2>
                    <p className="text-[10px] text-text-secondary mt-1 font-mono uppercase tracking-tighter">
                        Mode: <span className="text-text-main">Neural Temporal Analysis</span> • <span className="text-primary-amber font-bold">{timestepTimeLabel}</span>
                    </p>
                </div>
                <div className="flex items-center space-x-2 bg-red-500/10 px-2 py-1 rounded border border-red-500/20">
                    <div className="h-2 w-2 rounded-full bg-red-500 animate-pulse shadow-[0_0_8px_rgba(239,68,68,0.5)]" />
                    <span className="text-[10px] font-black text-red-500 uppercase tracking-widest">SIGINT_LIVE</span>
                </div>
            </div>

            <div className="flex-grow animate-fade-in relative">
                <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={activeSpectrum} margin={{ top: 5, right: 10, left: -20, bottom: 5 }}>
                        <defs>
                            <linearGradient id="colorPower" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#FFBF00" stopOpacity={0.4}/>
                                <stop offset="95%" stopColor="#FFBF00" stopOpacity={0}/>
                            </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="2 2" stroke="rgba(75, 85, 99, 0.1)" vertical={false} />
                        <XAxis 
                            dataKey="frequency" 
                            type="number" 
                            domain={['dataMin', 'dataMax']} 
                            tick={{ fontSize: 9, fill: '#6b7280', fontWeight: 'bold' }} 
                            axisLine={{ stroke: '#4b5563', strokeOpacity: 0.2 }}
                            tickLine={false}
                            unit="MHz"
                            label={{ value: 'Frequency Axis (Recurrent Domain)', position: 'bottom', offset: -10, fill: '#4b5563', fontSize: 8, fontWeight: 'bold', letterSpacing: '0.1em' }}
                        />
                        <YAxis 
                            domain={[-120, -20]} 
                            tick={{ fontSize: 9, fill: '#6b7280', fontWeight: 'bold' }} 
                            axisLine={{ stroke: '#4b5563', strokeOpacity: 0.2 }}
                            tickLine={false}
                            unit="dB"
                        />
                        <Tooltip
                            contentStyle={{ backgroundColor: '#111827', border: '1px solid rgba(255, 191, 0, 0.3)', fontSize: '10px', boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.5)' }}
                            labelStyle={{ color: '#FFBF00', fontWeight: 'bold', textTransform: 'uppercase', marginBottom: '4px' }}
                            itemStyle={{ color: '#e5e7eb', padding: '0' }}
                            formatter={(value: any) => [`${Number(value).toFixed(2)} dBm`, 'Power']}
                            labelFormatter={(label) => `Freq: ${Number(label).toFixed(2)} MHz`}
                        />
                        <Area
                            type="monotone"
                            dataKey="power"
                            name="Power"
                            stroke="#FFBF00"
                            strokeWidth={2}
                            fillOpacity={1}
                            fill="url(#colorPower)"
                            animationDuration={300}
                        />
                        {visualizerData[currentTimestep]?.anomalies.map((anomaly, index) => (
                            <ReferenceArea
                                key={index}
                                x1={anomaly.frequencyStart}
                                x2={anomaly.frequencyEnd}
                                fill="rgba(239, 68, 68, 0.15)"
                                stroke="rgba(239, 68, 68, 0.5)"
                                strokeDasharray="4 4"
                            />
                        ))}
                        <ReferenceLine y={-95} stroke="rgba(75, 85, 99, 0.5)" strokeDasharray="3 3" label={{ value: 'NOISE_FLOOR', position: 'right', fill: '#4b5563', fontSize: 8, fontWeight: 'bold' }} />
                    </AreaChart>
                </ResponsiveContainer>
            </div>

            <div className="flex items-center space-x-6 mt-6 pt-4 border-t border-secondary/10">
                <button onClick={() => setIsPlaying(!isPlaying)} className="group p-3 bg-base-300 rounded-full hover:bg-primary-amber transition-all shadow-[0_4px_10px_rgba(0,0,0,0.3)] hover:shadow-primary-amber/30 active:scale-95">
                    {isPlaying ? <PauseIcon className="w-5 h-5 group-hover:text-base-100" /> : <PlayIcon className="w-5 h-5 group-hover:text-base-100" />}
                </button>
                <div className="flex-grow space-y-2">
                    <div className="flex justify-between items-center text-[10px] font-bold text-text-secondary uppercase tracking-widest">
                        <span>Temporal Progression</span>
                        <span className="text-text-main bg-base-300 px-2 py-0.5 rounded border border-secondary/20">Frame {currentTimestep + 1} of {totalTimesteps}</span>
                    </div>
                    <input
                        type="range" min="0" max={totalTimesteps - 1}
                        value={currentTimestep} onChange={e => onTimestepChange(parseInt(e.target.value, 10))}
                        className="w-full h-1.5 rounded-lg appearance-none cursor-pointer bg-base-300 accent-primary-amber"
                    />
                </div>
            </div>
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { FileCodeIcon } from './icons/FileCodeIcon';
import type { FileAnalysisReport } from '../types';
import { MAX_FILE_SIZE_BYTES } from '../constants.ts';
import { ColumnDetectionError } from '../utils/csvParser';

interface ParseOptions {
    manualFreqIndex?: number;
    manualPowerIndex?: number;
    manualTimeIndex?: number;
}

interface FileUploadProps {
  onFileChange: (file: File | null) => void;
  onRunFileAnalysis: (file: File | Blob, options?: ParseOptions) => void;
  uploadedFile: File | null;
  analysisReport: FileAnalysisReport | null;
  analysisError: Error | string | null;
}

const StatBox: React.FC<{ label: string, value: string | number, sub?: string, color?: string }> = ({ label, value, sub, color = 'text-text-main' }) => (
    <div className="bg-base-300/40 p-3 rounded border border-secondary/10 flex flex-col justify-between">
        <p className="text-[9px] text-text-secondary uppercase font-black tracking-widest mb-1">{label}</p>
        <div>
            <p className={`text-sm font-bold font-mono ${color}`}>{value}</p>
            {sub && <p className="text-[8px] text-text-secondary/60 uppercase font-bold">{sub}</p>}
        </div>
    </div>
);

export const FileUpload: React.FC<FileUploadProps> = ({ onFileChange, onRunFileAnalysis, uploadedFile, analysisReport, analysisError }) => {
  const [isDragOver, setIsDragOver] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isLargeFile, setIsLargeFile] = useState(false);
  const [manualFreqIndex, setManualFreqIndex] = useState<number | string>('');
  const [manualPowerIndex, setManualPowerIndex] = useState<number | string>('');
  const [manualTimeIndex, setManualTimeIndex] = useState<number | string>('');

  useEffect(() => {
    if (!analysisError || !uploadedFile) {
        setManualFreqIndex('');
        setManualPowerIndex('');
        setManualTimeIndex('');
    }
  }, [analysisError, uploadedFile]);

  useEffect(() => {
    if (uploadedFile) {
      setIsLargeFile(uploadedFile.size > MAX_FILE_SIZE_BYTES);
      if (uploadedFile.size <= MAX_FILE_SIZE_BYTES) {
        onRunFileAnalysis(uploadedFile);
      }
    } else {
      setIsLargeFile(false);
    }
  }, [uploadedFile]);

  const handleFileChangeInternal = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files ? event.target.files[0] : null;
    onFileChange(file);
  };

  const handleClearFile = (e: React.MouseEvent) => {
    e.stopPropagation(); 
    onFileChange(null);
    if(fileInputRef.current) fileInputRef.current.value = "";
  }

  const handleConfirmSelection = () => {
    if (uploadedFile && manualFreqIndex !== '' && manualPowerIndex !== '') {
        onRunFileAnalysis(uploadedFile, {
            manualFreqIndex: Number(manualFreqIndex),
            manualPowerIndex: Number(manualPowerIndex),
            manualTimeIndex: manualTimeIndex !== '' ? Number(manualTimeIndex) : undefined
        });
    }
  };

  const baseClasses = "border border-dashed rounded-md p-4 transition-all duration-300";
  const idleClasses = "cursor-pointer bg-base-100/50 border-secondary hover:border-primary-amber hover:bg-primary-amber/5";
  const dragClasses = isDragOver ? 'border-primary-amber scale-105 bg-primary-amber/10' : 'border-secondary';

  const renderContent = () => {
      if (analysisError instanceof ColumnDetectionError) {
        return (
            <div className={`${baseClasses} border-amber-500/80 text-left animate-fade-in bg-amber-500/5`}>
                <div className="flex justify-between items-center mb-4">
                    <p className="font-bold text-amber-400 text-[10px] uppercase tracking-widest">Manual Emitter Mapping</p>
                    <button onClick={handleClearFile} className="text-[10px] text-text-secondary hover:text-red-400">&times;</button>
                </div>
                <div className="space-y-3">
                    <select value={manualFreqIndex} onChange={e => setManualFreqIndex(e.target.value)} className="w-full bg-base-300 text-xs border border-secondary/50 p-2 rounded">
                        <option value="">Select Frequency Axis...</option>
                        {analysisError.headers.map((h, i) => <option key={i} value={i}>{i}: {h}</option>)}
                    </select>
                    <select value={manualPowerIndex} onChange={e => setManualPowerIndex(e.target.value)} className="w-full bg-base-300 text-xs border border-secondary/50 p-2 rounded">
                        <option value="">Select Power Amplitude...</option>
                        {analysisError.headers.map((h, i) => <option key={i} value={i}>{i}: {h}</option>)}
                    </select>
                    <button onClick={handleConfirmSelection} className="btn-primary w-full py-2 text-xs">Run Spectral Audit</button>
                </div>
            </div>
        );
      }

      if (analysisReport) {
          return (
              <div className="animate-fade-in space-y-4">
                  <div className={`${baseClasses} border-primary-amber/30 bg-primary-amber/5 relative`}>
                      <div className="flex justify-between items-center mb-4">
                          <div className="flex items-center gap-2">
                              <div className="h-2 w-2 bg-primary-amber rounded-full animate-pulse" />
                              <p className="text-[10px] font-black text-primary-amber uppercase tracking-widest">Mission Data Profile</p>
                          </div>
                          <button onClick={handleClearFile} className="text-[10px] text-text-secondary hover:text-red-400 font-bold">EJECT</button>
                      </div>

                      <div className="grid grid-cols-2 gap-2">
                          <StatBox label="Identifier" value={analysisReport.fileName.substring(0, 15)} sub="Source Log" />
                          <StatBox label="Resolution" value={analysisReport.columnCount} sub="Channels" />
                          <StatBox label="Payload" value={analysisReport.rowCount.toLocaleString()} sub="Data Points" />
                          <StatBox label="Duration" value={analysisReport.timeStats ? `${analysisReport.timeStats.durationSeconds.toFixed(1)}s` : 'N/A'} sub="T-Span" />
                      </div>

                      <div className="mt-2 grid grid-cols-1 gap-2">
                          <div className="bg-base-300/60 p-3 rounded border border-secondary/10">
                              <p className="text-[9px] text-text-secondary uppercase font-black tracking-widest mb-1">Spectral Range</p>
                              <p className="text-[10px] font-mono text-primary-amber">
                                  {analysisReport.stats.frequency.min.toFixed(2)} - {analysisReport.stats.frequency.max.toFixed(2)} MHz
                              </p>
                          </div>
                          <div className="bg-base-300/60 p-3 rounded border border-secondary/10">
                              <p className="text-[9px] text-text-secondary uppercase font-black tracking-widest mb-1">Noise Floor / Peak</p>
                              <div className="flex justify-between font-mono text-[10px]">
                                  <span className="text-text-secondary">{analysisReport.stats.power.min.toFixed(1)} dBm</span>
                                  <span className="text-primary-amber font-bold">{analysisReport.stats.power.max.toFixed(1)} dBm</span>
                              </div>
                          </div>
                      </div>
                  </div>
              </div>
          );
      }

      return (
        <div
            className={`${baseClasses} ${idleClasses} ${dragClasses} flex flex-col items-center justify-center text-center`}
            onClick={() => fileInputRef.current?.click()}
            onDragOver={e => { e.preventDefault(); setIsDragOver(true); }}
            onDragLeave={() => setIsDragOver(false)}
            onDrop={e => { e.preventDefault(); setIsDragOver(false); onFileChange(e.dataTransfer.files[0]); }}
            style={{ minHeight: '140px' }}
        >
            <FileCodeIcon className="w-8 h-8 mb-3 opacity-40 text-text-secondary" />
            <p className="text-[10px] font-black text-primary-amber uppercase tracking-widest">Uplink SIGINT Capture</p>
            <p className="text-[8px] text-text-secondary/60 uppercase mt-1">.CSV / .TXT / .LOG (50MB MAX)</p>
        </div>
      );
  }

  return (
    <div>
      <input type="file" ref={fileInputRef} onChange={handleFileChangeInternal} className="hidden" accept=".csv,.txt,.log" />
      {renderContent()}
    </div>
  );
};

import * as tf from '@tensorflow/tfjs';
import { DetectionTarget } from '../types.ts';
import type { SimulationParams, AnalysisResult, FileAnalysisReport, SpectrumDataPoint, Anomaly } from '../types.ts';

const MIN_DBM = -110;
const MAX_DBM = -20;
const RANGE = MAX_DBM - MIN_DBM;

const normalize = (val: number) => (val - MIN_DBM) / RANGE;
const denormalize = (val: number) => (val * RANGE) + MIN_DBM;

const buildLSTMAutoencoder = (seqLen: number, numBins: number): tf.LayersModel => {
    const model = tf.sequential();
    model.add(tf.layers.lstm({ units: 128, inputShape: [seqLen, numBins], returnSequences: false, dropout: 0.1 }));
    model.add(tf.layers.repeatVector({ n: seqLen }));
    model.add(tf.layers.lstm({ units: 128, returnSequences: true }));
    model.add(tf.layers.timeDistributed({ layer: tf.layers.dense({ units: numBins, activation: 'sigmoid' }) }));
    model.compile({ optimizer: tf.train.adam(0.0005), loss: 'meanSquaredError' });
    return model;
};

export const generateDeceptionScenario = async (
    params: SimulationParams,
    analysisContent?: string,
): Promise<AnalysisResult> => {
    const timesteps = params.timesteps;
    const bins = 256; 
    const seqLen = 8; 

    const fileReport: FileAnalysisReport | null = analysisContent ? JSON.parse(analysisContent) : null;
    const baselinePower = fileReport?.stats.power.avg ?? -95;
    const freqMin = fileReport?.stats.frequency.min ?? 2400;
    const freqMax = fileReport?.stats.frequency.max ?? 2500;
    const freqRange = freqMax - freqMin;

    const inputData = tf.tidy(() => {
        const frames = [];
        for (let i = 0; i < 100; i++) {
            frames.push(tf.randomNormal([bins], normalize(baselinePower), 0.02));
        }
        const sequences = [];
        for (let i = 0; i <= frames.length - seqLen; i++) {
            sequences.push(tf.stack(frames.slice(i, i + seqLen)));
        }
        return tf.stack(sequences);
    });

    const model = buildLSTMAutoencoder(seqLen, bins);
    await model.fit(inputData, inputData, { epochs: 12, batchSize: 16, verbose: 0 });

    const visualizerData = [];
    let scenarioText = `## SIGINT INTELLIGENCE REPORT: TACTICAL RECURRENT PHASE\n\n`;
    scenarioText += `**Operational Objective:** ${params.detectionTarget}\n`;
    scenarioText += `**System Architecture:** PHANTOM-LSTM Deep-Recurrent Autoencoder\n\n`;

    const threshold = (100 - params.sensitivity) / 3000; 

    for (let t = 0; t < timesteps; t++) {
        const { spectrum, stepAnomalies } = tf.tidy(() => {
            const testSeq = tf.randomNormal([1, seqLen, bins], normalize(baselinePower), 0.03);
            let evalSeq = testSeq;
            let classification = "STOCHASTIC_ENVIRONMENT";
            let countermeasure = "Standard monitoring protocol.";

            // Simulate tactical threats based on mission parameters
            const isAnomalousFrame = (t % 3 === 2); 
            if (isAnomalousFrame) {
                const center = Math.floor(Math.random() * bins);
                let spikeWidth = 8;
                let powerDelta = 0.3;

                switch(params.detectionTarget) {
                    case DetectionTarget.DRONE_CONTROL_LINK:
                        classification = "DRONE_C2_LINK (FHSS)";
                        countermeasure = "Execute reactive frequency hopping; activate directional jamming.";
                        spikeWidth = 4; powerDelta = 0.45;
                        break;
                    case DetectionTarget.GPS_SPOOFING_SIGS:
                        classification = "GNSS_SPOOF_PEAK";
                        countermeasure = "Switch to inertial navigation; initiate PLL nulling.";
                        spikeWidth = 2; powerDelta = 0.55;
                        break;
                    case DetectionTarget.WIDEBAND_JAMMING:
                        classification = "BARRAGE_JAMMING";
                        countermeasure = "Shift operational frequency to edge-band; activate look-through.";
                        spikeWidth = 60; powerDelta = 0.25;
                        break;
                    default:
                        classification = "NON_STOCHASTIC_EMITTER";
                        countermeasure = "Maintain passive audit; investigate source.";
                        spikeWidth = 10; powerDelta = 0.35;
                }

                const spike = tf.oneHot(tf.tensor1d(Array.from({length: spikeWidth}, (_, i) => Math.max(0, Math.min(bins-1, center - Math.floor(spikeWidth/2) + i))), 'int32'), bins).sum(0).expandDims(0).expandDims(0);
                evalSeq = testSeq.add(spike.mul(powerDelta));
            }

            const prediction = model.predict(evalSeq) as tf.Tensor;
            const mse = tf.sub(evalSeq, prediction).square().mean().dataSync()[0];

            const anomalies: Anomaly[] = [];
            if (mse > threshold) {
                const centerFreq = freqMin + (Math.random() * freqRange);
                anomalies.push({
                    description: `Neural manifold violation detected. MSE: ${mse.toExponential(3)}. Emitter exhibits coherent non-stochastic structure.`,
                    frequencyStart: centerFreq - (freqRange * 0.05),
                    frequencyEnd: centerFreq + (freqRange * 0.05),
                    classification,
                    countermeasure
                });
            }

            const lastFrame = evalSeq.slice([0, seqLen - 1, 0], [1, 1, bins]).dataSync() as Float32Array;
            const spec: SpectrumDataPoint[] = Array.from(lastFrame).map((val, i) => ({
                frequency: freqMin + (i * (freqRange / bins)),
                power: denormalize(val)
            }));

            return { spectrum: spec, stepAnomalies: anomalies };
        });

        visualizerData.push({ spectrum, anomalies: stepAnomalies });
        scenarioText += `## Timestep ${t + 1}\n`;
        if (stepAnomalies.length > 0) {
            scenarioText += `**ALERT:** Recurrent engine failed to reconstruct spectral manifold. Signal signature identified as **${stepAnomalies[0].classification}**. Non-stochastic features detected.\n\n`;
        } else {
            scenarioText += `Environmental physics consistent with background baseline. No coherent anomalies detected.\n\n`;
        }
    }

    inputData.dispose();
    model.dispose();

    return { scenario: scenarioText, visualizerData, timeStats: fileReport?.timeStats };
};

import React, { useState, useEffect, useMemo } from 'react';
import {
  ResponsiveContainer,
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ReferenceArea,
  ReferenceLine
} from 'recharts';
import type { TimestepData, TimeStats } from '../types';
import { PlayIcon } from './icons/PlayIcon.tsx';
import { PauseIcon } from './icons/PauseIcon.tsx';
import { ChartBarIcon } from './icons/ChartBarIcon.tsx';
import { Loader } from './Loader.tsx';

interface DataVisualizerProps {
  visualizerData: TimestepData[];
  currentTimestep: number;
  onTimestepChange: React.Dispatch<React.SetStateAction<number>>;
  isLoading: boolean;
  timeStats: TimeStats | null;
}

const formatAbsoluteTime = (timestamp: number) => {
    return new Date(timestamp).toLocaleTimeString([], { 
        hour12: true, 
        hour: '2-digit', 
        minute: '2-digit', 
        second: '2-digit',
        fractionalSecondDigits: 2 
    } as any);
}

export const DataVisualizer: React.FC<DataVisualizerProps> = ({
    visualizerData,
    currentTimestep,
    onTimestepChange,
    isLoading,
    timeStats
}) => {
    const [isPlaying, setIsPlaying] = useState(false);
    const totalTimesteps = visualizerData?.length || 0;

    useEffect(() => {
        let interval: ReturnType<typeof setInterval>;
        if (isPlaying && totalTimesteps > 1) {
            interval = setInterval(() => {
                onTimestepChange(prev => (prev + 1) % totalTimesteps);
            }, 1200);
        }
        return () => clearInterval(interval);
    }, [isPlaying, onTimestepChange, totalTimesteps]);

    const activeSpectrum = useMemo(() => {
        return visualizerData[currentTimestep]?.spectrum || [];
    }, [visualizerData, currentTimestep]);

    const missionClock = useMemo(() => {
        if (!timeStats || totalTimesteps === 0) return 'T+00:00:00.00';
        const durationPerStep = timeStats.durationSeconds / totalTimesteps;
        const relativeOffset = currentTimestep * durationPerStep;
        if (timeStats.start > 1000000000) {
            return formatAbsoluteTime(timeStats.start + (relativeOffset * 1000));
        }
        return `T+${relativeOffset.toFixed(2)}s`;
    }, [timeStats, currentTimestep, totalTimesteps]);

    if (isLoading) {
        return <div className="flex flex-col items-center justify-center h-full text-text-secondary"><Loader size="lg" /><p className="mt-4 text-xs font-bold animate-pulse tracking-widest text-primary-amber uppercase">Syncing Recurrent State...</p></div>;
    }

    if (!visualizerData || totalTimesteps === 0) {
        return (
            <div className="flex flex-col items-center justify-center h-full text-text-secondary text-center opacity-40">
                <ChartBarIcon className="w-16 h-16 mb-4" />
                <h2 className="text-xl font-display text-text-main">AWAITING SIGNAL DATA</h2>
                <p className="mt-2 text-[10px] uppercase tracking-widest">Connect to spectrum feed or upload capture</p>
            </div>
        );
    }

    return (
        <div className="flex flex-col h-full">
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h2 className="text-sm font-bold text-primary-amber uppercase tracking-[0.2em]">
                        Phantom Signal HUD
                    </h2>
                    <p className="text-[10px] text-text-secondary mt-1 font-mono uppercase">
                        Mode: <span className="text-text-main">Neural Temporal Analysis</span> • <span className="text-primary-amber font-bold">{missionClock}</span>
                    </p>
                </div>
                <div className="flex items-center space-x-2 bg-red-500/10 px-2 py-1 rounded border border-red-500/20">
                    <div className="h-2 w-2 rounded-full bg-red-500 animate-pulse" />
                    <span className="text-[10px] font-black text-red-500 uppercase tracking-widest">SIGINT_LIVE</span>
                </div>
            </div>

            <div className="flex-grow animate-fade-in relative group">
                {/* Visual indicator of the Time Axis on the graph */}
                <div className="absolute top-0 right-0 p-2 text-[8px] font-mono text-secondary opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
                    X-AXIS: FREQUENCY (MHz) | SYNC: {missionClock}
                </div>

                <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={activeSpectrum} margin={{ top: 5, right: 10, left: -20, bottom: 5 }}>
                        <defs>
                            <linearGradient id="colorPower" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#FFBF00" stopOpacity={0.4}/>
                                <stop offset="95%" stopColor="#FFBF00" stopOpacity={0}/>
                            </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="2 2" stroke="rgba(75, 85, 99, 0.1)" vertical={false} />
                        <XAxis 
                            dataKey="frequency" 
                            type="number" 
                            domain={['dataMin', 'dataMax']} 
                            tick={{ fontSize: 9, fill: '#6b7280', fontWeight: 'bold' }} 
                            axisLine={{ stroke: '#4b5563', strokeOpacity: 0.2 }}
                            tickLine={false}
                            unit="MHz"
                        />
                        <YAxis 
                            domain={[-120, -20]} 
                            tick={{ fontSize: 9, fill: '#6b7280', fontWeight: 'bold' }} 
                            axisLine={{ stroke: '#4b5563', strokeOpacity: 0.2 }}
                            tickLine={false}
                            unit="dB"
                        />
                        <Tooltip
                            contentStyle={{ backgroundColor: '#111827', border: '1px solid rgba(255, 191, 0, 0.3)', fontSize: '10px' }}
                            labelStyle={{ color: '#FFBF00', fontWeight: 'bold' }}
                            itemStyle={{ color: '#e5e7eb' }}
                            labelFormatter={(val) => `Frequency: ${Number(val).toFixed(2)} MHz | Mission Clock: ${missionClock}`}
                        />
                        <Area
                            type="monotone"
                            dataKey="power"
                            name="Power"
                            stroke="#FFBF00"
                            strokeWidth={2}
                            fillOpacity={1}
                            fill="url(#colorPower)"
                            animationDuration={300}
                        />
                        {visualizerData[currentTimestep]?.anomalies.map((anomaly, index) => (
                            <ReferenceArea
                                key={index}
                                x1={anomaly.frequencyStart}
                                x2={anomaly.frequencyEnd}
                                fill="rgba(239, 68, 68, 0.15)"
                                stroke="rgba(239, 68, 68, 0.5)"
                                strokeDasharray="4 4"
                            />
                        ))}
                        <ReferenceLine y={-95} stroke="rgba(75, 85, 99, 0.5)" strokeDasharray="3 3" label={{ value: 'NOISE_FLOOR', position: 'right', fill: '#4b5563', fontSize: 8, fontWeight: 'bold' }} />
                    </AreaChart>
                </ResponsiveContainer>
            </div>

            <div className="flex items-center space-x-6 mt-6 pt-4 border-t border-secondary/10">
                <button onClick={() => setIsPlaying(!isPlaying)} className="group p-3 bg-base-300 rounded-full hover:bg-primary-amber transition-all shadow-lg active:scale-95">
                    {isPlaying ? <PauseIcon className="w-5 h-5 group-hover:text-base-100" /> : <PlayIcon className="w-5 h-5 group-hover:text-base-100" />}
                </button>
                <div className="flex-grow space-y-2">
                    <div className="flex justify-between items-center text-[10px] font-bold text-text-secondary uppercase tracking-widest">
                        <span>Temporal Progression</span>
                        <span className="text-primary-amber font-mono">{missionClock}</span>
                    </div>
                    <input
                        type="range" min="0" max={totalTimesteps - 1}
                        value={currentTimestep} onChange={e => onTimestepChange(parseInt(e.target.value, 10))}
                        className="w-full h-1.5 rounded-lg appearance-none cursor-pointer bg-base-300 accent-primary-amber"
                    />
                </div>
            </div>
        </div>
    );
};
